/**
 * Sage → ISAFlow Import Script for Brightsphere Technologies
 * Reads raw Sage data and inserts into ISAFlow database tables.
 */

import { neon } from '@neondatabase/serverless';

const DATABASE_URL = process.env.DATABASE_URL!;
const sql = neon(DATABASE_URL);
const COMPANY_ID = 'd27bac33-cdc0-4e58-bf6b-709c1597d41c';

// ── Sage category → ISAFlow account type mapping ────────────────────────────
const SAGE_CATEGORY_TO_TYPE: Record<number, string> = {
  1: 'revenue',     // Sales
  2: 'expense',     // Cost of Sales
  3: 'revenue',     // Other Income
  4: 'expense',     // Expenses
  5: 'asset',       // Non-Current Assets (Fixed Assets)
  6: 'asset',       // Current Assets
  7: 'liability',   // Non-Current Liabilities
  8: 'liability',   // Current Liabilities
  9: 'equity',      // Owners Equity
  10: 'expense',    // Income Tax
};

const SAGE_CATEGORY_TO_SUBTYPE: Record<number, string> = {
  1: 'sales',
  2: 'cost_of_sales',
  3: 'other_income',
  4: 'operating_expenses',
  5: 'fixed_assets',
  6: 'current_assets',
  7: 'long_term_liabilities',
  8: 'current_liabilities',
  9: 'equity',
  10: 'tax',
};

const SAGE_CATEGORY_TO_NORMAL: Record<number, string> = {
  1: 'credit',  2: 'debit',  3: 'credit',
  4: 'debit',   5: 'debit',  6: 'debit',
  7: 'credit',  8: 'credit', 9: 'credit', 10: 'debit',
};

// ── Raw Sage data (embedded from browser pull) ──────────────────────────────

const SAGE_ACCOUNTS = ACCOUNTS_PLACEHOLDER;
const SAGE_CUSTOMERS = CUSTOMERS_PLACEHOLDER;
const SAGE_SUPPLIERS = SUPPLIERS_PLACEHOLDER;
const SAGE_AP_INVOICES = AP_INVOICES_PLACEHOLDER;
const SAGE_CUSTOMER_RETURNS = CUSTOMER_RETURNS_PLACEHOLDER;
const SAGE_SUPPLIER_PAYMENTS = SUPPLIER_PAYMENTS_PLACEHOLDER;
const SAGE_JOURNAL_ENTRIES = JOURNAL_ENTRIES_PLACEHOLDER;

async function importAccounts() {
  console.log('\n=== Importing Chart of Accounts ===');
  let imported = 0;
  for (const a of SAGE_ACCOUNTS) {
    const catId = a.Category?.ID ?? 4;
    const accountCode = a.ID > 0 ? String(a.ID) : `SYS-${Math.abs(a.ID)}`;
    const accountType = SAGE_CATEGORY_TO_TYPE[catId] || 'expense';
    const accountSubtype = SAGE_CATEGORY_TO_SUBTYPE[catId] || 'operating_expenses';
    const normalBalance = SAGE_CATEGORY_TO_NORMAL[catId] || 'debit';

    try {
      await sql`
        INSERT INTO gl_accounts (company_id, account_code, account_name, account_type, account_subtype,
          normal_balance, is_active, is_system_account, description, display_order, imported_from)
        VALUES (${COMPANY_ID}::UUID, ${accountCode}, ${a.Name}, ${accountType}, ${accountSubtype},
          ${normalBalance}, ${a.Active}, ${a.AccountType === 2}, ${a.Description || a.Category?.Description || ''},
          ${a.Category?.Order ?? 0}, ${'sage_cloud'})
        ON CONFLICT DO NOTHING
      `;
      imported++;
    } catch (e: any) {
      console.error(`  SKIP account ${a.Name}: ${e.message}`);
    }
  }
  console.log(`  Imported ${imported}/${SAGE_ACCOUNTS.length} accounts`);
}

async function importCustomers() {
  console.log('\n=== Importing Customers ===');
  let imported = 0;
  for (const c of SAGE_CUSTOMERS) {
    try {
      await sql`
        INSERT INTO customers (company_id, name, email, phone, vat_number, contact_person,
          credit_limit, is_active, opening_balance, accepts_electronic_invoices,
          auto_allocate_receipts, mobile)
        VALUES (${COMPANY_ID}::UUID, ${c.Name}, ${c.Email || null}, ${c.Telephone || null},
          ${c.TaxReference || null}, ${c.ContactName || null}, ${c.CreditLimit || 0},
          ${c.Active}, ${c.Balance || 0}, ${c.AcceptsElectronicInvoices || false},
          ${c.AutoAllocateToOldestInvoice || false}, ${c.Mobile || null})
        ON CONFLICT DO NOTHING
      `;
      imported++;
    } catch (e: any) {
      console.error(`  SKIP customer ${c.Name}: ${e.message}`);
    }
  }
  console.log(`  Imported ${imported}/${SAGE_CUSTOMERS.length} customers`);
}

async function importSuppliers() {
  console.log('\n=== Importing Suppliers ===');
  let imported = 0;
  for (const s of SAGE_SUPPLIERS) {
    try {
      await sql`
        INSERT INTO suppliers (company_id, name, email, phone, vat_number, contact_person,
          is_active, opening_balance, mobile, fax, web_address,
          auto_allocate_payments)
        VALUES (${COMPANY_ID}::UUID, ${s.Name}, ${s.Email || null}, ${s.Telephone || null},
          ${s.TaxReference || null}, ${s.ContactName || null},
          ${s.Active}, ${s.Balance || 0}, ${s.Mobile || null}, ${s.Fax || null},
          ${s.WebAddress || null}, ${s.AutoAllocateToOldestInvoice || false})
        ON CONFLICT DO NOTHING
      `;
      imported++;
    } catch (e: any) {
      console.error(`  SKIP supplier ${s.Name}: ${e.message}`);
    }
  }
  console.log(`  Imported ${imported}/${SAGE_SUPPLIERS.length} suppliers`);
}

async function main() {
  console.log('Starting Sage → ISAFlow import for Brightsphere Technologies');
  console.log(`Company ID: ${COMPANY_ID}`);

  await importAccounts();
  await importCustomers();
  await importSuppliers();

  console.log('\n=== Summary ===');
  const counts = await sql`
    SELECT
      (SELECT COUNT(*) FROM gl_accounts WHERE company_id = ${COMPANY_ID}::UUID) as accounts,
      (SELECT COUNT(*) FROM customers WHERE company_id = ${COMPANY_ID}::UUID) as customers,
      (SELECT COUNT(*) FROM suppliers WHERE company_id = ${COMPANY_ID}::UUID) as suppliers
  `;
  console.log(counts[0]);
  console.log('\nImport complete!');
}

main().catch(console.error);

