async () => {
  // Pull all data and download as a single combined JSON
  const company = await (await fetch('/services/Company/Current', { credentials: 'include' })).json();

  const taxTypes = await (await fetch('/services/TaxType/Get', { credentials: 'include' })).json();

  const fetchAll = async (url) => {
    const all = [];
    let skip = 0, total = Infinity;
    while (skip < total) {
      const res = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json;charset=UTF-8' },
        body: JSON.stringify({ FilterId: url.includes('Account') ? 2 : 0, Search: '', Skip: skip, Take: 200,
          ...(url.includes('Account') ? { OrderBy: 'AccountCategory_Order asc, Account_Type DESC, Account_Name Asc' } : {}) }),
        credentials: 'include'
      });
      const json = await res.json();
      total = json.TotalResults || 0;
      all.push(...(json.Results || []));
      skip += 200;
    }
    return all;
  };

  const accounts = await fetchAll('/services/Account/GetWithFilter');
  const customers = await fetchAll('/services/Customer/GetWithFilter');
  const suppliers = await fetchAll('/services/Supplier/GetWithFilter');
  const arInvoices = await fetchAll('/services/TaxInvoice/GetWithFilter');
  const apInvoices = await fetchAll('/services/SupplierInvoice/GetWithFilter');
  const receipts = await fetchAll('/services/CustomerReceipt/GetWithFilter');
  const supplierPayments = await fetchAll('/services/SupplierPayment/GetWithFilter');
  const customerReturns = await fetchAll('/services/CustomerReturn/GetWithFilter');
  const journalEntries = await (await fetch('/services/JournalEntry/Get', { credentials: 'include' })).json();
  const bankTransactions = await (await fetch('/services/BankTransaction/Get', { credentials: 'include' })).json();

  const allData = {
    company, taxTypes, accounts, customers, suppliers,
    arInvoices, apInvoices, receipts, supplierPayments,
    customerReturns, journalEntries, bankTransactions
  };

  const blob = new Blob([JSON.stringify(allData)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'sage-complete-export.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);

  return {
    company: 1, taxTypes: taxTypes.length, accounts: accounts.length,
    customers: customers.length, suppliers: suppliers.length,
    arInvoices: arInvoices.length, apInvoices: apInvoices.length,
    receipts: receipts.length, supplierPayments: supplierPayments.length,
    customerReturns: customerReturns.length, journalEntries: journalEntries.length,
    bankTransactions: bankTransactions.length
  };
}

