    ['CustomerReceipt', 0], ['SupplierPayment', 0], ['CustomerReturn', 0]
  ];
  const results = {};
  for (const [ep, fid] of endpoints) {
    try {
      const res = await fetch(`/services/${ep}/GetWithFilter`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json;charset=UTF-8' },
        body: JSON.stringify({ FilterId: fid, Search: '', Skip: 0, Take: 5 }),
        credentials: 'include'
      });
      const text = await res.text();
      if (text.startsWith('<')) {
        results[ep] = { error: 'HTML response', first50: text.slice(0, 50) };
      } else {
        const json = JSON.parse(text);
        results[ep] = { ok: true, total: json.TotalResults };
      }
    } catch(e) {
      results[ep] = { error: e.message };
    }
  }
  return results;
}

