        VALUES (${CID}::UUID, ${bankAccountId}::UUID, ${txnDate}::DATE, ${t.total || 0},
          ${t.desc || t.memo || ''}, ${t.ref || null},
          ${t.recon ? 'reconciled' : 'unmatched'})`;
