      ok++;
    } catch (e: any) { console.error(`  ERR ${inv.DocumentNumber}: ${e.message?.slice(0, 100)}`); }
  }
  console.log(`  AP Invoices: ${ok} imported, ${skip} skipped (no supplier match)`);
}

async function main() {
  console.log('=== Sage → ISAFlow Import: Brightsphere Technologies ===\n');
