/**
 * Bank Transactions API
 * GET /api/accounting/bank-transactions - List transactions (with filters)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBankTransactions } from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const {
      bank_account_id, reconciliation_id, status,
      from_date, to_date, from_amount, to_amount,
      search, limit, offset,
    } = req.query;
    const result = await getBankTransactions(companyId, {
      bankAccountId: bank_account_id ? String(bank_account_id) : undefined,
      reconciliationId: reconciliation_id ? String(reconciliation_id) : undefined,
      status: status ? String(status) : undefined,
      fromDate: from_date ? String(from_date) : undefined,
      toDate: to_date ? String(to_date) : undefined,
      fromAmount: from_amount ? String(from_amount) : undefined,
      toAmount: to_amount ? String(to_amount) : undefined,
      search: search ? String(search) : undefined,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  } catch (err) {
    log.error('Failed to get bank transactions', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to get bank transactions');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

export async function getBankTransactions(companyId: string, filters?: BankTxFilters): Promise<{
  transactions: BankTransaction[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 100;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    // JOINs to resolve suggestion display names so allocations persist across page refresh
    // sga = suggested GL account, ss = suggested supplier, sc = suggested client
    if (filters?.reconciliationId) {
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               sga.account_name AS suggested_gl_account_name, sga.account_code AS suggested_gl_account_code,
               COALESCE(ss.company_name, ss.name) AS suggested_supplier_name,
               sc.name AS suggested_client_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts sga ON sga.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers ss ON ss.id = bt.suggested_supplier_id
        LEFT JOIN customers sc ON sc.id = bt.suggested_client_id
        WHERE bt.reconciliation_id = ${filters.reconciliationId}::UUID
        ORDER BY bt.transaction_date DESC, bt.amount DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM bank_transactions
        WHERE reconciliation_id = ${filters.reconciliationId}::UUID
      `) as Row[];
    } else if (filters?.bankAccountId && filters?.status) {
      // date range + amount range + full-text search via always-present params (no conditional SQL fragments)
      const searchPattern = filters.search ? `%${filters.search}%` : '%';
      const fromDateVal = filters.fromDate || '1900-01-01';
      const toDateVal = filters.toDate || '2099-12-31';
      const fromAmountVal = filters.fromAmount || '-999999999';
      const toAmountVal = filters.toAmount || '999999999';
      // 'imported' tab shows both imported and allocated (not-yet-reviewed) transactions
      const statusArr = filters.status === 'imported'
        ? ['imported', 'allocated']
        : [filters.status];
      rows = (await sql`
        SELECT bt.*, ga.account_name AS bank_account_name,
               sga.account_name AS suggested_gl_account_name, sga.account_code AS suggested_gl_account_code,
               COALESCE(ss.company_name, ss.name) AS suggested_supplier_name,
               sc.name AS suggested_client_name
        FROM bank_transactions bt
        LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        LEFT JOIN gl_accounts sga ON sga.id = bt.suggested_gl_account_id
        LEFT JOIN suppliers ss ON ss.id = bt.suggested_supplier_id
        LEFT JOIN customers sc ON sc.id = bt.suggested_client_id
        WHERE bt.bank_account_id = ${filters.bankAccountId}::UUID
          AND bt.status = ANY(${statusArr}::TEXT[])
          AND bt.transaction_date >= ${fromDateVal}
          AND bt.transaction_date <= ${toDateVal}
          AND bt.amount >= ${fromAmountVal}::NUMERIC
          AND bt.amount <= ${toAmountVal}::NUMERIC
          AND (bt.description ILIKE ${searchPattern} OR bt.reference ILIKE ${searchPattern})
        ORDER BY bt.transaction_date DESC, bt.amount DESC

/** Maps UI tabs to bank_transactions.status values */
function tabToStatus(tab: Tab): string {
  if (tab === 'new') return 'imported';
  if (tab === 'excluded') return 'excluded';
  return 'matched';
}

export default function BankTransactionsPage() {
  const [transactions, setTransactions] = useState<BankTx[]>([]);
  const [glAccounts, setGlAccounts] = useState<SelectOption[]>([]);
  const [suppliers, setSuppliers] = useState<SelectOption[]>([]);
  const [customers, setCustomers] = useState<SelectOption[]>([]);
