 * Sage Auto-Pull API
 * GET /api/accounting/migration/sage-pull?step=scripts
 *   → Returns JavaScript snippets the browser extension injects into Sage
 *
 * POST /api/accounting/migration/sage-pull
 *   → Receives raw Sage data from the browser, maps to ISAFlow format, returns mapped data
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest, withRole } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  buildSageAccountsFetchScript,
  buildSageFetchScript,
  buildSageCompanyFetchScript,
  mapSageAccounts,
  mapSageCustomers,
  mapSageSuppliers,
  mapSageARInvoices,
  mapSageAPInvoices,
  mapSageBankAccounts,
  mapSageBankTransactions,
  mapSageJournalEntries,
  mapSageReceipts,
  mapSageSupplierPayments,
  mapSageItems,
  mapSageTaxTypes,
  mapSageCustomerNotes,
  mapSageSupplierReturns,
} from '@/modules/accounting/services/sageAutoImportService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    // Return the JS scripts the browser extension will inject into Sage
    const scripts = {
      company: buildSageCompanyFetchScript(),
      accounts: buildSageAccountsFetchScript(),
      customers: buildSageFetchScript('/services/Customer/GetWithFilter', 200),
      suppliers: buildSageFetchScript('/services/Supplier/GetWithFilter', 200),
      arInvoices: buildSageFetchScript('/services/TaxInvoice/GetWithFilter', 200),
      apInvoices: buildSageFetchScript('/services/SupplierInvoice/GetWithFilter', 200),
      bankAccounts: buildSageFetchScript('/services/BankAccount/GetWithFilter', 200),
      bankTransactions: buildSageFetchScript('/services/BankTransaction/GetWithFilter', 200),
      journalEntries: buildSageFetchScript('/services/JournalEntry/GetWithFilter', 200),
      receipts: buildSageFetchScript('/services/Receipt/GetWithFilter', 200),
      supplierPayments: buildSageFetchScript('/services/SupplierPayment/GetWithFilter', 200),
      items: buildSageFetchScript('/services/Item/GetWithFilter', 200),
      taxTypes: buildSageFetchScript('/services/TaxType/GetWithFilter', 200),
      customerNotes: buildSageFetchScript('/services/CustomerNote/GetWithFilter', 200),
      supplierReturns: buildSageFetchScript('/services/SupplierReturn/GetWithFilter', 200),
    };

    return apiResponse.success(res, { scripts });
  }

  if (req.method === 'POST') {
    const { step, rawData } = req.body as { step: string; rawData: unknown };

    if (!step || !rawData) {
      return apiResponse.validationError(res, { step: 'step and rawData are required' });
    }

    log.info('Sage auto-pull received', { companyId, step }, 'migration');

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const data = rawData as any;

    switch (step) {
      case 'accounts': {
        const mapped = mapSageAccounts(data.Results || []);
        return apiResponse.success(res, {
          step: 'accounts',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'customers': {
        const mapped = mapSageCustomers(data.Results || []);
        return apiResponse.success(res, {
          step: 'customers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'suppliers': {
        const mapped = mapSageSuppliers(data.Results || []);
        return apiResponse.success(res, {
          step: 'suppliers',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'arInvoices': {
        const mapped = mapSageARInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'arInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'apInvoices': {
        const mapped = mapSageAPInvoices(data.Results || []);
        return apiResponse.success(res, {
          step: 'apInvoices',
          total: data.TotalResults || mapped.length,
          records: mapped,
        });
      }
      case 'company': {
        return apiResponse.success(res, {
          step: 'company',
          record: {
            name: data.Name,
            taxNumber: data.TaxNumber,
            registrationNumber: data.RegistrationNumber,
            currency: data.CurrencySymbol,
            takeOnDate: data.TakeOnBalanceDate,
          },
        });
      }
      case 'bankAccounts': {
        const mapped = mapSageBankAccounts(data.Results || []);
        return apiResponse.success(res, { step: 'bankAccounts', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'bankTransactions': {
        const mapped = mapSageBankTransactions(data.Results || []);
        return apiResponse.success(res, { step: 'bankTransactions', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'journalEntries': {
        const mapped = mapSageJournalEntries(data.Results || []);
        return apiResponse.success(res, { step: 'journalEntries', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'receipts': {
        const mapped = mapSageReceipts(data.Results || []);
        return apiResponse.success(res, { step: 'receipts', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'supplierPayments': {
        const mapped = mapSageSupplierPayments(data.Results || []);
        return apiResponse.success(res, { step: 'supplierPayments', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'items': {
        const mapped = mapSageItems(data.Results || []);
        return apiResponse.success(res, { step: 'items', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'taxTypes': {
        const mapped = mapSageTaxTypes(data.Results || []);
        return apiResponse.success(res, { step: 'taxTypes', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'customerNotes': {
        const mapped = mapSageCustomerNotes(data.Results || []);
        return apiResponse.success(res, { step: 'customerNotes', total: data.TotalResults || mapped.length, records: mapped });
      }
      case 'supplierReturns': {
        const mapped = mapSageSupplierReturns(data.Results || []);
        return apiResponse.success(res, { step: 'supplierReturns', total: data.TotalResults || mapped.length, records: mapped });
      }
      default:
        return apiResponse.badRequest(res, `Unknown step: ${step}`);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// Super admin only — ISAFlow internal tool
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withRole('super_admin')(withErrorHandler(handler)) as any);

/**
 * Sage Auto-Import Service
 *
 * Pulls data from Sage Business Cloud's internal REST APIs via the user's
 * authenticated browser session. The browser acts as a proxy — ISAFlow
 * injects fetch calls into the Sage tab and receives structured JSON.
 *
 * Discovered endpoints (Sage internal, session-cookie auth):
 *   POST /services/Account/GetWithFilter    → Chart of Accounts
 *   POST /services/Customer/GetWithFilter   → Customers
 *   POST /services/Supplier/GetWithFilter   → Suppliers
 *   POST /services/TaxInvoice/GetWithFilter → Customer Invoices (AR)
 *   POST /services/SupplierInvoice/GetWithFilter → Supplier Invoices (AP)
 *   GET  /services/Company/Current          → Company info
 */

