    FROM customer_invoices ci 
    LEFT JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
    WHERE ci.company_id = \${cid}
    GROUP BY COALESCE(ci.client_id, ci.customer_id), c.name
    ORDER BY cnt DESC
  \`;
  console.log('\\n=== INVOICES BY CUSTOMER ===');
  byClient.forEach(r => console.log('  ', r.cust_id?.substring(0,8) || 'NULL', r.name || '(no name)', r.cnt, 'R', Number(r.total).toFixed(0)));

  // Check customer payments
  const pmts = await sql\`SELECT COUNT(*) as cnt, SUM(total_amount) as total FROM customer_payments WHERE company_id = \${cid}\`;
  console.log('\\n=== CUSTOMER PAYMENTS ===');
  console.log(pmts[0]);

  // Check suppliers
  const supps = await sql\`SELECT id, name FROM suppliers WHERE company_id = \${cid} ORDER BY name\`;
  console.log('\\n=== SUPPLIERS (' + supps.length + ') ===');
  supps.forEach(s => console.log('  ', s.id.substring(0,8), s.name));

  // Check supplier invoices
  const sinv = await sql\`SELECT COUNT(*) as cnt, SUM(total_amount) as total FROM supplier_invoices WHERE company_id = \${cid}\`;
  console.log('\\n=== SUPPLIER INVOICES ===');
  console.log(sinv[0]);

  // Check supplier payments  
  const spmts = await sql\`SELECT COUNT(*) as cnt, SUM(total_amount) as total FROM supplier_payments WHERE company_id = \${cid}\`;
  console.log('\\n=== SUPPLIER PAYMENTS ===');
  console.log(spmts[0]);

  // Check bank transactions
  const btx = await sql\`SELECT COUNT(*) as cnt FROM bank_transactions WHERE company_id = \${cid}\`;
  console.log('\\n=== BANK TRANSACTIONS ===');
  console.log(btx[0]);

  // Check GL accounts
  const gl = await sql\`SELECT COUNT(*) as cnt FROM gl_accounts WHERE company_id = \${cid}\`;
  console.log('\\n=== GL ACCOUNTS ===');
  console.log(gl[0]);

})().catch(e => console.error(e));
