export function getActiveTabId(
  pathname: string,
  query: Record<string, string | string[] | undefined>,
): string {
  if (pathname === '/accounting') return 'dashboard';
  if (pathname.startsWith('/accounting/migration')) return 'import';
  if (pathname.startsWith('/accounting/sage-migration')) return 'import';

  // Customers
  if (
    pathname.startsWith('/accounting/customers') ||
    pathname.startsWith('/accounting/customer-') ||
    pathname.startsWith('/accounting/recurring-invoices') ||
    pathname.startsWith('/accounting/credit-notes') ||
    pathname.startsWith('/accounting/write-offs') ||
    pathname.startsWith('/accounting/debtors-manager') ||
    pathname.startsWith('/accounting/ar-aging') ||
    pathname.startsWith('/accounting/statement-run') ||
    pathname.startsWith('/accounting/dunning') ||
    pathname === '/accounting/reports/sales-by-customer' ||
    pathname === '/accounting/reports/unallocated-receipts' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'customer')
  ) {
    return 'customers';
  }

  // Suppliers
  if (
    pathname.startsWith('/accounting/suppliers') ||
    pathname.startsWith('/accounting/supplier-') ||
    pathname.startsWith('/accounting/purchase-orders') ||
    pathname.startsWith('/accounting/batch-payments') ||
    pathname.startsWith('/accounting/ap-aging') ||
    pathname === '/accounting/reports/purchases-by-supplier' ||
    pathname === '/accounting/reports/unallocated-payments' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'supplier')
  ) {
    return 'suppliers';
  }

  // Items
  if (
    pathname.startsWith('/accounting/items') ||
    pathname.startsWith('/accounting/item-') ||
    pathname === '/accounting/reports/item-listing' ||
    pathname === '/accounting/reports/sales-by-item' ||
    pathname === '/accounting/reports/purchases-by-item' ||
    pathname === '/accounting/reports/item-movement' ||
    pathname === '/accounting/reports/item-valuation' ||
    pathname === '/accounting/reports/item-quantities'
  ) {
    return 'items';
  }

  // Banking
  if (pathname.startsWith('/accounting/bank-')) return 'banking';

  // Accounts
  if (
    pathname.startsWith('/accounting/chart-of-accounts') ||
    pathname.startsWith('/accounting/journal-entries') ||
    pathname.startsWith('/accounting/recurring-journals') ||
    pathname.startsWith('/accounting/fiscal-periods') ||
    pathname.startsWith('/accounting/default-accounts') ||
    pathname.startsWith('/accounting/currencies') ||
    pathname.startsWith('/accounting/exchange-rates')
  ) {
    return 'accounts';
  }

  // VAT
  if (
    pathname.startsWith('/accounting/vat-') ||
    pathname.startsWith('/accounting/drc-vat') ||
    pathname === '/accounting/reports/vat-return'
  ) {
    return 'vat';
  }

  // Accountant's Area
  if (
    pathname.startsWith('/accounting/trial-balance') ||
    pathname.startsWith('/accounting/opening-balances') ||
    pathname.startsWith('/accounting/assets') ||
    pathname.startsWith('/accounting/depreciation') ||
    pathname.startsWith('/accounting/year-end') ||
    pathname.startsWith('/accounting/cost-centres') ||
    pathname.startsWith('/accounting/business-units') ||
    pathname.startsWith('/accounting/budgets')
  ) {
    return 'accountants';
  }

  // Group
  if (pathname.startsWith('/accounting/group')) return 'group';

  // SARS
  if (pathname.startsWith('/accounting/sars')) return 'sars';

  // Tools
  if (
    pathname.startsWith('/accounting/document-capture') ||
    pathname.startsWith('/accounting/approvals') ||
    pathname.startsWith('/accounting/company-settings') ||
    pathname.startsWith('/accounting/my-account') ||
    pathname.startsWith('/accounting/cash-flow-forecast') ||
    pathname.startsWith('/accounting/time-tracking') ||
    pathname.startsWith('/accounting/user-access') ||
    pathname.startsWith('/accounting/audit-log') ||
    pathname.startsWith('/accounting/gl-import') ||
    pathname.startsWith('/accounting/duplicates') ||
    pathname.startsWith('/accounting/data-archiving') ||
    pathname.startsWith('/accounting/webhooks') ||
    pathname.startsWith('/accounting/recurring-transactions')
  ) {
    return 'tools';
  }

  if (pathname.startsWith('/accounting/reports')) return 'reports';

  // Payroll
  if (pathname.startsWith('/payroll')) return 'payroll';

  return 'dashboard';
}

export function isLinkActive(href: string, asPath: string): boolean {
  const parts = href.split('?');
  const itemPath = parts[0] as string;
  const qs = parts[1];
  return asPath.startsWith(itemPath) && (!qs || asPath.includes(qs));
}

/**
 * Cost Centres Action API
 * POST — update, toggle, or delete a cost centre
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  updateCostCentre, toggleCostCentre, deleteCostCentre,
} from '@/modules/accounting/services/costCentreService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { companyId } = req as CompanyApiRequest;
  const { action, id, ...data } = req.body;
  if (!id) return apiResponse.badRequest(res, 'id required');

  try {
    switch (action) {
      case 'update': {
        const updated = await updateCostCentre(companyId, id, data);
        return apiResponse.success(res, updated);
      }
      case 'toggle':
        await toggleCostCentre(companyId, id, data.isActive !== false);
        return apiResponse.success(res, { toggled: true });
      case 'delete':
        await deleteCostCentre(companyId, id);
        return apiResponse.success(res, { deleted: true });
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    log.error('Cost centre action failed', { action, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Cost Centre (Analysis Code) Service
 * Phase 5: Custom reporting dimensions for GL entries
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type CcType = 'cc1' | 'cc2';

export interface CostCentre {
  id: string;
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType: CcType;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface CostCentreInput {
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType?: CcType;
}

export async function getCostCentres(companyId: string, activeOnly = false, _ccType?: CcType): Promise<CostCentre[]> {
  const rows = activeOnly
    ? ((await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} AND is_active = true ORDER BY code`) as Row[])
    : ((await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} ORDER BY code`) as Row[]);
  return rows.map(mapRow);
}

export async function getCostCentre(id: string): Promise<CostCentre | null> {
  const rows = (await sql`SELECT * FROM cost_centres WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapRow(rows[0]) : null;
}

export async function createCostCentre(companyId: string, input: CostCentreInput, _userId: string): Promise<CostCentre> {
  const rows = (await sql`
    INSERT INTO cost_centres (company_id, code, name, description)
    VALUES (${companyId}, ${input.code}, ${input.name}, ${input.description || null})
    RETURNING *
  `) as Row[];
  log.info('Created cost centre', { id: rows[0].id, code: input.code }, 'accounting');
  return mapRow(rows[0]);
}

export async function updateCostCentre(companyId: string, id: string, input: Partial<CostCentreInput>): Promise<CostCentre> {
  const rows = (await sql`
    UPDATE cost_centres SET
      code = COALESCE(${input.code || null}, code),
      name = COALESCE(${input.name || null}, name),
      description = COALESCE(${input.description || null}, description),
      department = COALESCE(${input.department || null}, department)
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Cost centre ${id} not found`);
  return mapRow(rows[0]);
}

export async function toggleCostCentre(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE cost_centres SET is_active = ${isActive} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

export async function deleteCostCentre(companyId: string, id: string): Promise<void> {
  // Check for usage in journal lines
  const usage = (await sql`
    SELECT COUNT(*) as cnt FROM gl_journal_lines WHERE cost_center_id = ${id}::UUID
  `) as Row[];
  if (Number(usage[0]?.cnt) > 0) {
    throw new Error('Cannot delete cost centre that is used in journal entries. Deactivate instead.');
  }
  await sql`DELETE FROM cost_centres WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

function mapRow(row: Row): CostCentre {
  return {
    id: String(row.id),
    code: String(row.code),
    name: String(row.name),
    description: row.description ? String(row.description) : undefined,
    department: row.department ? String(row.department) : undefined,
    ccType: (row.cc_type || 'cc1') as CcType,
    isActive: Boolean(row.is_active),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

-- Migration 200: Accounting Module Foundation
-- PRD-060: FibreFlow Accounting Module - Phase 1
-- GL Engine, Chart of Accounts, Fiscal Periods

-- ── GL Accounts (Chart of Accounts) ─────────────────────────────────────────

CREATE TABLE IF NOT EXISTS gl_accounts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_code VARCHAR(20) UNIQUE NOT NULL,
  account_name VARCHAR(100) NOT NULL,
  account_type VARCHAR(20) NOT NULL CHECK (account_type IN ('asset', 'liability', 'equity', 'revenue', 'expense')),
  account_subtype VARCHAR(50),
  parent_account_id UUID REFERENCES gl_accounts(id),
  is_active BOOLEAN DEFAULT true,
  is_system_account BOOLEAN DEFAULT false,
  description TEXT,
  normal_balance VARCHAR(10) NOT NULL CHECK (normal_balance IN ('debit', 'credit')),
  level INT DEFAULT 1,
  display_order INT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_gl_accounts_code ON gl_accounts(account_code);
CREATE INDEX idx_gl_accounts_parent ON gl_accounts(parent_account_id);
CREATE INDEX idx_gl_accounts_type ON gl_accounts(account_type);
CREATE INDEX idx_gl_accounts_active ON gl_accounts(is_active);

-- ── Fiscal Periods ──────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS fiscal_periods (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  period_name VARCHAR(50) NOT NULL,
  period_number INT NOT NULL,
  fiscal_year INT NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  status VARCHAR(20) DEFAULT 'open' CHECK (status IN ('open', 'closing', 'closed', 'locked')),
  closed_by UUID,
  closed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(fiscal_year, period_number)
);

CREATE INDEX idx_fiscal_periods_year ON fiscal_periods(fiscal_year);
CREATE INDEX idx_fiscal_periods_status ON fiscal_periods(status);
CREATE INDEX idx_fiscal_periods_dates ON fiscal_periods(start_date, end_date);

-- ── GL Journal Entries ──────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS gl_journal_entries (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  entry_number VARCHAR(20) UNIQUE,
  entry_date DATE NOT NULL,
  fiscal_period_id UUID REFERENCES fiscal_periods(id),
  description TEXT,
  source VARCHAR(30) DEFAULT 'manual' CHECK (source IN (
    'manual', 'auto_invoice', 'auto_payment', 'auto_grn',
    'auto_credit_note', 'auto_bank_recon'
  )),
  source_document_id UUID,
  status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'posted', 'reversed')),
  posted_by UUID,
  posted_at TIMESTAMPTZ,
  reversed_by UUID,
  reversed_at TIMESTAMPTZ,
  reversal_of_id UUID REFERENCES gl_journal_entries(id),
  created_by UUID NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX idx_gl_je_date ON gl_journal_entries(entry_date);
CREATE INDEX idx_gl_je_period ON gl_journal_entries(fiscal_period_id);
CREATE INDEX idx_gl_je_source ON gl_journal_entries(source);
CREATE INDEX idx_gl_je_status ON gl_journal_entries(status);
CREATE INDEX idx_gl_je_number ON gl_journal_entries(entry_number);

-- ── GL Journal Lines ────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS gl_journal_lines (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  journal_entry_id UUID NOT NULL REFERENCES gl_journal_entries(id) ON DELETE CASCADE,
  gl_account_id UUID NOT NULL REFERENCES gl_accounts(id),
  debit NUMERIC(15,2) DEFAULT 0 CHECK (debit >= 0),
  credit NUMERIC(15,2) DEFAULT 0 CHECK (credit >= 0),
  description TEXT,
  project_id UUID,
  cost_center_id UUID,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  CONSTRAINT chk_debit_or_credit CHECK (NOT (debit > 0 AND credit > 0))
);

CREATE INDEX idx_gl_jl_entry ON gl_journal_lines(journal_entry_id);
CREATE INDEX idx_gl_jl_account ON gl_journal_lines(gl_account_id);
CREATE INDEX idx_gl_jl_project ON gl_journal_lines(project_id) WHERE project_id IS NOT NULL;

-- ── GL Account Balances (cache) ─────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS gl_account_balances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  gl_account_id UUID NOT NULL REFERENCES gl_accounts(id),
  fiscal_period_id UUID NOT NULL REFERENCES fiscal_periods(id),
  debit_total NUMERIC(15,2) DEFAULT 0,
  credit_total NUMERIC(15,2) DEFAULT 0,
  balance NUMERIC(15,2) DEFAULT 0,
  updated_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE(gl_account_id, fiscal_period_id)
);

CREATE INDEX idx_gl_ab_account ON gl_account_balances(gl_account_id);
CREATE INDEX idx_gl_ab_period ON gl_account_balances(fiscal_period_id);

-- ── Triggers ────────────────────────────────────────────────────────────────

-- Auto-generate entry_number on INSERT
CREATE OR REPLACE FUNCTION generate_journal_entry_number()
RETURNS TRIGGER AS $$
DECLARE
  entry_year INT;
  next_seq INT;
BEGIN
  entry_year := EXTRACT(YEAR FROM NEW.entry_date);
  SELECT COALESCE(MAX(
    CAST(SPLIT_PART(entry_number, '-', 3) AS INT)
  ), 0) + 1 INTO next_seq
  FROM gl_journal_entries
  WHERE entry_number LIKE 'JE-' || entry_year || '-%';

  NEW.entry_number := 'JE-' || entry_year || '-' || LPAD(next_seq::TEXT, 5, '0');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_gl_je_entry_number
  BEFORE INSERT ON gl_journal_entries
  FOR EACH ROW
  WHEN (NEW.entry_number IS NULL)
  EXECUTE FUNCTION generate_journal_entry_number();

-- Enforce balanced entries on post
CREATE OR REPLACE FUNCTION enforce_balanced_entry()
RETURNS TRIGGER AS $$
DECLARE
  total_debit NUMERIC(15,2);
  total_credit NUMERIC(15,2);
BEGIN
  IF NEW.status = 'posted' AND (OLD.status IS NULL OR OLD.status = 'draft') THEN
    SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0)

