/**
 * Bank Transactions API
 * GET /api/accounting/bank-transactions - List transactions (with filters)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBankTransactions } from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const {
      bank_account_id, reconciliation_id, status,
      from_date, to_date, from_amount, to_amount,
      search, limit, offset,
    } = req.query;
    const result = await getBankTransactions(companyId, {
      bankAccountId: bank_account_id ? String(bank_account_id) : undefined,
      reconciliationId: reconciliation_id ? String(reconciliation_id) : undefined,
      status: status ? String(status) : undefined,
      fromDate: from_date ? String(from_date) : undefined,
      toDate: to_date ? String(to_date) : undefined,
      fromAmount: from_amount ? String(from_amount) : undefined,
      toAmount: to_amount ? String(to_amount) : undefined,
      search: search ? String(search) : undefined,
      limit: limit ? Number(limit) : undefined,
      offset: offset ? Number(offset) : undefined,
    });
    return apiResponse.success(res, result);
  } catch (err) {
    log.error('Failed to get bank transactions', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to get bank transactions');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Business Units Page
 * CRUD for departments used as BU dimension on bank transactions and GL journal lines
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { Building2, Plus, Loader2, ToggleLeft, ToggleRight, Pencil } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

interface BusinessUnit {
  id: string;
  name: string;
  code: string;
  description?: string;
  isActive: boolean;
  staffCount?: number;
}

export default function BusinessUnitsPage() {
  const [items, setItems] = useState<BusinessUnit[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [busy, setBusy] = useState('');
  const [error, setError] = useState('');
  const [form, setForm] = useState({ name: '', code: '', description: '' });
  const [search, setSearch] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    const res = await apiFetch('/api/accounting/cost-centres', { credentials: 'include' });
    const json = await res.json();
    const rows: BusinessUnit[] = (json.data || []).map((d: BusinessUnit) => ({
      id: d.id, name: d.name, code: d.code,
      description: d.description, isActive: d.isActive,
      staffCount: d.staffCount,
    }));
    setItems(rows);
    setLoading(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(''); setBusy('save');
    try {
      if (editId) {
        const res = await apiFetch(`/api/departments/${editId}`, {
          method: 'PUT', headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ name: form.name, code: form.code, description: form.description }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed');
      } else {
        const res = await apiFetch('/api/accounting/cost-centres', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          credentials: 'include',
          body: JSON.stringify({ name: form.name, code: form.code, description: form.description }),
        });
        const json = await res.json();
        if (!res.ok) throw new Error(json.message || 'Failed');
      }
      setShowForm(false); setEditId(null);
      setForm({ name: '', code: '', description: '' });
      await load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setBusy(''); }
  };

  const startEdit = (bu: BusinessUnit) => {
    setForm({ name: bu.name, code: bu.code, description: bu.description || '' });
    setEditId(bu.id); setShowForm(true);
  };

  const toggleActive = async (bu: BusinessUnit) => {
    setBusy(bu.id);
    try {
      await apiFetch(`/api/departments/${bu.id}`, {
        method: 'PUT', headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ isActive: !bu.isActive }),
      });
      await load();
    } catch { /* ignore */ }
    setBusy('');
  };

  const lowerSearch = search.toLowerCase();
  const filteredItems = items.filter(bu =>
    !search ||
    bu.name.toLowerCase().includes(lowerSearch) ||
    bu.code.toLowerCase().includes(lowerSearch) ||
    (bu.description || '').toLowerCase().includes(lowerSearch)
  );

  return (
    <AppLayout>
