  const [search, setSearch] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    const res = await apiFetch(`/api/accounting/cost-centres?cc_type=${activeTab}`, { credentials: 'include' });
    const json = await res.json();
    setItems(json.data?.items || []);
    setLoading(false);
