      await apiFetch('/api/accounting/cost-centres-action', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        credentials: 'include', body: JSON.stringify({ action, id, ...extra }),
      });
      await load();
    } catch { /* ignore */ }
    setBusy('');
