  const searchPattern = filters.search ? `%${filters.search}%` : '%';
  const fromDateVal = filters.fromDate || '1900-01-01';
  const toDateVal = filters.toDate || '2099-12-31';
  const fromAmountVal = filters.fromAmount || '-999999999';
  const toAmountVal = filters.toAmount || '999999999';
  // 'imported' tab shows both imported and allocated (not-yet-reviewed) transactions
  let statusArr: string[];
  if (filters.status === 'imported') {
    if (filters.allocationFilter === 'unallocated') statusArr = ['imported'];
    else if (filters.allocationFilter === 'allocated') statusArr = ['allocated'];
    else statusArr = ['imported', 'allocated'];
  } else {
    statusArr = [filters.status];
  }
  // Transaction direction filter
  const txTypeCondition = filters.txType === 'spent' ? 'AND bt.amount < 0'
    : filters.txType === 'received' ? 'AND bt.amount > 0' : '';
  // Allocation type filter
  const allocTypeCondition = filters.allocType && filters.allocType !== 'all'
    ? `AND bt.allocation_type = '${filters.allocType}'` : '';
  // Has suggestion filter
  const hasSuggestionCondition = filters.hasSuggestion === 'yes'
    ? 'AND (bt.suggested_gl_account_id IS NOT NULL OR bt.suggested_supplier_id IS NOT NULL OR bt.suggested_client_id IS NOT NULL)'
    : filters.hasSuggestion === 'no'
      ? 'AND bt.suggested_gl_account_id IS NULL AND bt.suggested_supplier_id IS NULL AND bt.suggested_client_id IS NULL'
      : '';
  // Sort direction
  const sortDir = filters.sortOrder === 'asc' ? 'ASC' : 'DESC';
  rows = (await sql.unsafe(`
    SELECT bt.*, ga.account_name AS bank_account_name,
           sga.account_name AS suggested_gl_account_name, sga.account_code AS suggested_gl_account_code,
           COALESCE(ss.company_name, ss.name) AS suggested_supplier_name,
           sc.name AS suggested_client_name
    FROM bank_transactions bt
    LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
    LEFT JOIN gl_accounts sga ON sga.id = bt.suggested_gl_account_id
    LEFT JOIN suppliers ss ON ss.id = bt.suggested_supplier_id
    LEFT JOIN customers sc ON sc.id = bt.suggested_client_id
    WHERE bt.bank_account_id = $1::UUID
      AND bt.status = ANY($2::TEXT[])
      AND bt.transaction_date >= $3
      AND bt.transaction_date <= $4
      AND bt.amount >= $5::NUMERIC
      AND bt.amount <= $6::NUMERIC
      AND (bt.description ILIKE $7 OR bt.reference ILIKE $7)
      ${txTypeCondition}
      ${allocTypeCondition}
      ${hasSuggestionCondition}
    ORDER BY bt.transaction_date ${sortDir}, bt.amount DESC
    LIMIT $8 OFFSET $9
  `, [filters.bankAccountId, statusArr, fromDateVal, toDateVal, fromAmountVal, toAmountVal, searchPattern, limit, offset])) as Row[];
  countRows = (await sql.unsafe(`
    SELECT COUNT(*) AS cnt FROM bank_transactions bt
    WHERE bt.bank_account_id = $1::UUID
      AND bt.status = ANY($2::TEXT[])
      AND bt.transaction_date >= $3
      AND bt.transaction_date <= $4
      AND bt.amount >= $5::NUMERIC
      AND bt.amount <= $6::NUMERIC
      AND (bt.description ILIKE $7 OR bt.reference ILIKE $7)
      ${txTypeCondition}
      ${allocTypeCondition}
