/**
 * Income Statement (P&L) Report API
 * GET /api/accounting/reports-income-statement
 *   ?period_start=YYYY-MM-DD&period_end=YYYY-MM-DD
 *   &project_id=UUID (optional)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getIncomeStatement } from '@/modules/accounting/services/financialReportingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { period_start, period_end, project_id, cost_centre_id, compare_start, compare_end } = req.query;
    if (!period_start || !period_end) {
      return apiResponse.badRequest(res, 'period_start and period_end are required');
    }

    const comparePeriod = compare_start && compare_end
      ? { start: String(compare_start), end: String(compare_end) }
      : undefined;

    const report = await getIncomeStatement(companyId,
      String(period_start),
      String(period_end),
      {
        projectId: project_id ? String(project_id) : undefined,
        costCentreId: cost_centre_id ? String(cost_centre_id) : undefined,
      },
      comparePeriod
    );
    return apiResponse.success(res, report);
  } catch (err) {
    log.error('Failed to get income statement', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to generate income statement');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Balance Sheet Report API
 * GET /api/accounting/reports-balance-sheet
 *   ?as_at_date=YYYY-MM-DD
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getBalanceSheet } from '@/modules/accounting/services/financialReportingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { as_at_date, cost_centre_id, compare_date } = req.query;
    if (!as_at_date) {
      return apiResponse.badRequest(res, 'as_at_date is required');
    }

    const report = await getBalanceSheet(companyId,
      String(as_at_date),
      cost_centre_id ? String(cost_centre_id) : undefined,
      compare_date ? String(compare_date) : undefined
    );
    return apiResponse.success(res, report);
  } catch (err) {
    log.error('Failed to get balance sheet', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to generate balance sheet');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

