          <div className="flex flex-col sm:flex-row items-start sm:items-end gap-3 mb-6">
            <div>
              <label className={LABEL_CLS}>Document Type</label>
              <select className={INPUT_CLS} value={docType} onChange={e => setDocType(e.target.value)}>
