                <div>
                  <div className="text-sm font-medium text-[var(--ff-text-primary)]">{opt.label}</div>
                  <div className="text-xs text-[var(--ff-text-tertiary)]">{opt.desc}</div>
                </div>
              </label>
            ))}
          </div>
