      {/* Shortcut Help Overlay — triggered by '?' */}
      <ShortcutHelpOverlay
        isOpen={shortcutHelpOpen}
        onClose={() => setShortcutHelpOpen(false)}
        shortcuts={globalShortcuts}
      />

      {/* Onboarding Tour */}
      <AccountingTour />
    </div>
  );
}

/**
 * Sidebar navigation using the same TABS config as the top-bar.
 * Hover a tab → flyout panel pops to the right via a portal on document.body.
 * Sub-sections cascade further right, also via portals so nothing is clipped.
 */

import { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronRight } from 'lucide-react';
import {
  TABS,
  getActiveTabId,
  isFlyout,
  isLinkActive,
  type Tab,
  type NavItem,
} from '../accounting/accountingNavConfig';

// ─── Shared styles ──────────────────────────────────────────────────────────

const panelCls = 'bg-gray-800 border border-gray-700 rounded-lg shadow-2xl min-w-[210px] py-1';

const linkCls = (active: boolean) =>
  `block px-4 py-1.5 text-sm whitespace-nowrap transition-colors ${
    active ? 'text-teal-400 bg-teal-500/10 font-medium' : 'text-gray-300 hover:text-white hover:bg-gray-700/50'
  }`;

// ─── Recursive section flyout using portals ─────────────────────────────────

function SectionFlyout({
  label,
  items,
  asPath,
  onNav,
  parentRight,
  parentTop,
}: {
  label: string;
  items: NavItem[];
  asPath: string;
  onNav: () => void;
  parentRight: number;
  parentTop: number;
}) {
  const [open, setOpen] = useState(false);
  const [subPos, setSubPos] = useState<{ top: number; left: number } | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cl = () => { if (timer.current) clearTimeout(timer.current); };
  const dl = () => { timer.current = setTimeout(() => setOpen(false), 150); };
  useEffect(() => () => cl(), []);

  const handleEnter = () => {
    cl();
    setOpen(true);
    if (ref.current) {
      const rect = ref.current.getBoundingClientRect();
      setSubPos({ top: rect.top, left: rect.right });
    }
  };

  return (
    <div ref={ref} onMouseEnter={handleEnter} onMouseLeave={dl}>
      <div className={`flex items-center justify-between px-4 py-2 text-sm cursor-default transition-colors ${
        open ? 'bg-gray-700 text-white' : 'text-gray-300 hover:text-gray-600'
      }`}>
        <span className="font-medium">{label}</span>
        <ChevronRight className="h-3.5 w-3.5 ml-4 flex-shrink-0" />
      </div>

      {open && subPos && createPortal(
        <div
          style={{ position: 'fixed', top: subPos.top, left: subPos.left, zIndex: 99999 }}
          className={panelCls}
          onMouseEnter={cl}
          onMouseLeave={dl}
        >
          {items.map(item => {
            if (!isFlyout(item)) {
              return (
                <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>
                  {item.label}
                </Link>
              );
            }
            // Nested section → recurse
            return (
              <SectionFlyout
                key={item.section}
                label={item.section}
                items={item.items}
                asPath={asPath}
                onNav={onNav}
                parentRight={subPos.left + 210}
                parentTop={subPos.top}
              />
            );
          })}
        </div>,
        document.body
      )}
    </div>
  );
}

// ─── Tab flyout content ─────────────────────────────────────────────────────

function TabFlyoutContent({ tab, asPath, onNav }: { tab: Tab; asPath: string; onNav: () => void }) {
  const hasSections = tab.items?.some(isFlyout) ?? false;

  return (
    <>
      {/* Quick actions */}
      {tab.topItems?.map(item => (
        <Link key={item.href} href={item.href} onClick={onNav}
          className="block px-4 py-2 text-sm text-teal-400 hover:bg-gray-700/50 transition-colors whitespace-nowrap">
          + {item.label}
        </Link>
      ))}
      {tab.topItems && tab.topItems.length > 0 && <div className="border-t border-gray-700 my-1" />}

      {/* Sections with sub-flyouts */}
      {hasSections && tab.items?.map(item => {
        if (!isFlyout(item)) {
          return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
        }
        return (
          <SectionFlyout
            key={item.section}
            label={item.section}
            items={item.items}
            asPath={asPath}
            onNav={onNav}
            parentRight={0}
            parentTop={0}
          />
        );
      })}

      {/* Flat items */}
      {!hasSections && tab.items?.map(item => {
        if (isFlyout(item)) return null;
        return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
      })}
    </>
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  const [flyout, setFlyout] = useState<{ tabId: string; top: number; left: number } | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cl = useCallback(() => { if (timer.current) { clearTimeout(timer.current); timer.current = null; } }, []);
  const dl = useCallback(() => { timer.current = setTimeout(() => setFlyout(null), 180); }, []);

  useEffect(() => { setFlyout(null); }, [router.pathname]);
  useEffect(() => () => cl(), [cl]);

  const openFlyout = useCallback((tabId: string, el: HTMLElement) => {
    cl();
    const rect = el.getBoundingClientRect();
    setFlyout({ tabId, top: rect.top, left: rect.right });
  }, [cl]);

  const flyoutTab = flyout ? TABS.find(t => t.id === flyout.tabId) : null;

  return (
    <>
      <nav className="flex-1 overflow-y-auto py-2">
        {TABS.map(tab => {
          const active = activeTabId === tab.id;
          const hasItems = !!(tab.items?.length);
          const isOpen = flyout?.tabId === tab.id;

          if (tab.href && !hasItems) {
            return (
              <Link key={tab.id} href={tab.href}
                className={`flex items-center px-4 py-2 text-sm font-medium transition-colors border-l-2 ${
                  active ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                    : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
                } ${collapsed ? 'justify-center px-0' : ''}`}
                title={collapsed ? tab.label : undefined}>
                {collapsed ? tab.label.slice(0, 2) : tab.label}
              </Link>
            );
          }

          return (
            <div key={tab.id}
              onMouseEnter={(e) => openFlyout(tab.id, e.currentTarget)}
              onMouseLeave={dl}
              className={`flex items-center justify-between px-4 py-2 text-sm font-medium cursor-pointer transition-colors border-l-2 ${
                active || isOpen ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                  : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
              } ${collapsed ? 'justify-center px-0' : ''}`}
              title={collapsed ? tab.label : undefined}>
              <span>{collapsed ? tab.label.slice(0, 2) : tab.label}</span>
              {!collapsed && <ChevronRight className={`w-3.5 h-3.5 flex-shrink-0 ${isOpen ? 'text-teal-400' : 'text-gray-500'}`} />}
            </div>
          );
        })}
      </nav>

      {/* First-level flyout via portal */}
      {flyoutTab && flyout && createPortal(
        <div
          style={{ position: 'fixed', top: flyout.top, left: flyout.left, zIndex: 99999 }}
          className={panelCls}
          onMouseEnter={cl}
          onMouseLeave={dl}
        >
          <TabFlyoutContent tab={flyoutTab} asPath={asPath} onNav={() => setFlyout(null)} />
        </div>,
        document.body
      )}
    </>
  );
}

/**
 * Accounting Tour — lightweight custom onboarding tour.
 * No external dependencies. Uses a spotlight overlay with a cutout.
 * Shows a welcome prompt for new users; can be restarted via useRestartTour().
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { X, ChevronLeft, ChevronRight, Compass } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import { TOUR_STEPS, getTooltipPosition, type TargetRect } from './tourConfig';

const PREF_KEY = 'onboarding_tour_completed';
const PADDING = 8;

export function AccountingTour() {
  const [showWelcome, setShowWelcome] = useState(false);
  const [active, setActive] = useState(false);
  const [step, setStep] = useState(0);
  const [targetRect, setTargetRect] = useState<TargetRect | null>(null);
  const [isMounted, setIsMounted] = useState(false);
  const rafRef = useRef<number | null>(null);

  useEffect(() => { setIsMounted(true); }, []);

  // Check if user is new — show a welcome prompt (not the tour itself)
  useEffect(() => {
    if (!isMounted) return;
    const check = async () => {
      try {
        const res = await apiFetch('/api/auth/preferences');
        const json = await res.json() as { data?: Record<string, string> };
        if (!json.data?.[PREF_KEY]) setShowWelcome(true);
      } catch (err) {
        log.warn('Failed to load tour preference', { error: err }, 'AccountingTour');
      }
    };
    void check();
  }, [isMounted]);

  const startTour = useCallback(() => {
    setShowWelcome(false);
    setActive(true);
  }, []);

  const dismissWelcome = useCallback(async () => {
    setShowWelcome(false);
    try {
      await apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences: { [PREF_KEY]: 'true' } }),
      });
    } catch { /* non-critical */ }
  }, []);

  const measureTarget = useCallback((stepIndex: number) => {
    const s = TOUR_STEPS[stepIndex];
    if (!s) return;
    const el = document.querySelector(s.target);
    if (!el) { setTargetRect(null); return; }
    const r = el.getBoundingClientRect();
    setTargetRect({
      top: r.top - PADDING,
      left: r.left - PADDING,
      width: r.width + PADDING * 2,
      height: r.height + PADDING * 2,
    });
  }, []);

  useEffect(() => {
    if (!active) return;
    measureTarget(step);
    const handleResize = () => measureTarget(step);
    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
      if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);
    };
  }, [active, step, measureTarget]);

  const completeTour = useCallback(async () => {
    setActive(false);
    try {
      await apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences: { [PREF_KEY]: 'true' } }),
      });
      log.info('Onboarding tour completed', {}, 'AccountingTour');
    } catch (err) {
      log.warn('Failed to save tour preference', { error: err }, 'AccountingTour');
    }
  }, []);

  const goNext = useCallback(() => {
    if (step < TOUR_STEPS.length - 1) setStep(s => s + 1);
    else void completeTour();
  }, [step, completeTour]);

  const goBack = useCallback(() => {
    if (step > 0) setStep(s => s - 1);
  }, [step]);

  if (!isMounted) return null;

  // Welcome prompt — non-intrusive card in the bottom-right corner
  if (showWelcome && !active) {
    return (
      <div className="fixed bottom-6 right-6 z-[9999] w-80 bg-white dark:bg-gray-900 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700 p-5 animate-in slide-in-from-bottom-4 fade-in duration-300">
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0 w-9 h-9 rounded-lg bg-teal-500/10 flex items-center justify-center">
            <Compass className="w-5 h-5 text-teal-500" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="text-sm font-semibold text-gray-900 dark:text-white">Welcome to ISAFlow!</h3>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-1 leading-relaxed">
              Want a quick tour of the key features? It only takes a moment.
            </p>
            <div className="flex items-center gap-2 mt-3">
              <button
                onClick={startTour}
                className="px-3 py-1.5 text-xs rounded-md bg-teal-600 hover:bg-teal-700 text-white transition-colors font-medium"
              >
                Show me around
              </button>
              <button
                onClick={() => void dismissWelcome()}
                className="px-3 py-1.5 text-xs rounded-md text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
              >
                Maybe later
              </button>
            </div>
          </div>
          <button onClick={() => void dismissWelcome()} className="flex-shrink-0 p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors" aria-label="Dismiss">
            <X className="w-3.5 h-3.5 text-gray-400" />
          </button>
        </div>
      </div>
    );
  }

  if (!active) return null;

  const currentStep = TOUR_STEPS[step]!;
  const tooltipPos = targetRect
    ? getTooltipPosition(targetRect, currentStep.position)
    : { top: window.innerHeight / 2 - 80, left: window.innerWidth / 2 - 160 };

  return (
    <div className="fixed inset-0 z-[9999] pointer-events-none">
      {/* Dark overlay with spotlight cutout */}
      {targetRect ? (
        <svg
          className="absolute inset-0 w-full h-full pointer-events-auto"
          onClick={(e) => { if (e.target === e.currentTarget) void completeTour(); }}
        >
          <defs>
            <mask id="tour-mask">
              <rect x="0" y="0" width="100%" height="100%" fill="white" />
              <rect x={targetRect.left} y={targetRect.top} width={targetRect.width} height={targetRect.height} rx="6" fill="black" />
            </mask>
          </defs>
          <rect x="0" y="0" width="100%" height="100%" fill="rgba(0,0,0,0.65)" mask="url(#tour-mask)" />
        </svg>
      ) : (
        <div className="absolute inset-0 bg-black/65 pointer-events-auto" onClick={() => void completeTour()} />
      )}

      {/* Highlight border */}
      {targetRect && (
        <div
          className="absolute rounded-md border-2 border-teal-400 pointer-events-none"
          style={{ top: targetRect.top, left: targetRect.left, width: targetRect.width, height: targetRect.height }}
        />
      )}

      {/* Tooltip */}
      <div
        className="absolute w-80 bg-white dark:bg-gray-900 rounded-xl shadow-2xl border border-gray-200 dark:border-gray-700 p-5 pointer-events-auto"
        style={{ top: tooltipPos.top, left: tooltipPos.left }}
      >
        <div className="flex items-start justify-between mb-2">
          <h3 className="text-sm font-semibold text-gray-900 dark:text-white">{currentStep.title}</h3>
          <button onClick={() => void completeTour()} className="p-1 rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors" aria-label="Skip tour">
            <X className="w-3.5 h-3.5 text-gray-400" />
          </button>
        </div>

        <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed mb-4">
          {currentStep.content}
        </p>

        <div className="flex items-center justify-between">
          <span className="text-xs text-gray-400">Step {step + 1} of {TOUR_STEPS.length}</span>
          <div className="flex items-center gap-2">
            <button onClick={() => void completeTour()} className="text-xs text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors">
              Skip Tour
            </button>
            {step > 0 && (
              <button onClick={goBack} className="flex items-center gap-1 px-2.5 py-1.5 text-xs rounded-md border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                <ChevronLeft className="w-3 h-3" />Back
              </button>
            )}
            <button onClick={goNext} className="flex items-center gap-1 px-2.5 py-1.5 text-xs rounded-md bg-teal-600 hover:bg-teal-700 text-white transition-colors font-medium">
              {step < TOUR_STEPS.length - 1 ? (<>Next <ChevronRight className="w-3 h-3" /></>) : 'Done'}
            </button>
          </div>
        </div>

        {/* Step dots */}
        <div className="flex items-center gap-1 mt-3 justify-center">
          {TOUR_STEPS.map((_, i) => (
            <div key={i} className={`rounded-full transition-all ${i === step ? 'w-4 h-1.5 bg-teal-500' : 'w-1.5 h-1.5 bg-gray-300 dark:bg-gray-600'}`} />
          ))}
        </div>
      </div>
    </div>
  );
}

/**
 * Hook to programmatically restart the tour (clears the preference and reloads).
 */
export function useRestartTour() {
  return useCallback(async () => {
    try {
      await apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences: { [PREF_KEY]: '' } }),
      });
      window.location.reload();
    } catch (err) {
      log.warn('Failed to reset tour preference', { error: err }, 'AccountingTour');
    }
  }, []);
}

