/**
 * Select — searchable dropdown with keyboard navigation, portal, multi-select.
 * // WORKING: Portal-based dropdown, full a11y, arrow/enter/escape keyboard nav
 */

import {
  useState,
  useRef,
  useEffect,
  useCallback,
  useId,
  type ReactNode,
  type KeyboardEvent,
} from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown, X, Check, Search } from 'lucide-react';
import { cn } from '@/utils/cn';

export interface SelectOption {
  value: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
}

// Shared base props
interface SelectBaseProps {
  options: SelectOption[];
  placeholder?: string;
  searchable?: boolean;
  label?: string;
  error?: string;
  disabled?: boolean;
  clearable?: boolean;
  className?: string;
  id?: string;
}

interface SingleSelectProps extends SelectBaseProps {
  multiple?: false;
  value: string | null;
  onChange: (value: string | null) => void;
}

interface MultiSelectProps extends SelectBaseProps {
  multiple: true;
  value: string[];
  onChange: (value: string[]) => void;
}

type SelectProps = SingleSelectProps | MultiSelectProps;

function useDropdownPosition(
  triggerRef: React.RefObject<HTMLDivElement | null>
) {
  const [pos, setPos] = useState({ top: 0, left: 0, width: 0 });

  const recalculate = useCallback(() => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    setPos({
      top: rect.bottom + window.scrollY + 4,
      left: rect.left + window.scrollX,
      width: rect.width,
    });
  }, [triggerRef]);

  return { pos, recalculate };
}

// WORKING: Select component (single and multi)
export function Select(props: SelectProps) {
  const {
    options,
    placeholder = 'Select…',
    searchable = false,
    label,
    error,
    disabled = false,
    clearable = false,
    className,
    id: externalId,
  } = props;

  const autoId = useId();
  const inputId = externalId ?? autoId;
  const labelId = `${inputId}-label`;
  const listboxId = `${inputId}-listbox`;

  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState<number>(-1);

  const triggerRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const { pos, recalculate } = useDropdownPosition(triggerRef);

  const isMulti = props.multiple === true;
  const selectedValues: string[] = isMulti
    ? (props.value as string[])
    : props.value
    ? [props.value as string]
    : [];

  const filteredOptions = searchable && search.trim()
    ? options.filter((o) =>
        o.label.toLowerCase().includes(search.toLowerCase())
      )
    : options;

  const openDropdown = useCallback(() => {
    if (disabled) return;
    recalculate();
    setOpen(true);
    setActiveIndex(-1);
  }, [disabled, recalculate]);

  const closeDropdown = useCallback(() => {
    setOpen(false);
    setSearch('');
    setActiveIndex(-1);
  }, []);

  function selectOption(option: SelectOption) {
    if (option.disabled) return;
    if (isMulti) {
      const current = props.value as string[];
      const next = current.includes(option.value)
        ? current.filter((v) => v !== option.value)
        : [...current, option.value];
      (props as MultiSelectProps).onChange(next);
    } else {
      (props as SingleSelectProps).onChange(option.value);
      closeDropdown();
    }
  }

  function clearSelection(e: React.MouseEvent) {
    e.stopPropagation();
    if (isMulti) {
      (props as MultiSelectProps).onChange([]);
    } else {
      (props as SingleSelectProps).onChange(null);
    }
  }

  function handleTriggerKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
      e.preventDefault();
      if (!open) openDropdown();
      else setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Escape') {
      closeDropdown();
    }
  }

  function handleListKeyDown(e: KeyboardEvent<HTMLUListElement>) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex >= 0 && filteredOptions[activeIndex]) {
        selectOption(filteredOptions[activeIndex]);
      }
    } else if (e.key === 'Escape') {
      closeDropdown();
    }
  }

  // Scroll active item into view
  useEffect(() => {
    if (!listRef.current || activeIndex < 0) return;
    const item = listRef.current.children[activeIndex] as HTMLElement | undefined;
    item?.scrollIntoView({ block: 'nearest' });
