/**
 * Select — searchable dropdown with keyboard navigation, portal, multi-select.
 * // WORKING: Portal-based dropdown, full a11y, arrow/enter/escape keyboard nav
 */

import {
  useState,
  useRef,
  useEffect,
  useCallback,
  useId,
  type ReactNode,
  type KeyboardEvent,
} from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown, X, Check, Search } from 'lucide-react';
import { cn } from '@/utils/cn';

export interface SelectOption {
  value: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
}

// Shared base props
interface SelectBaseProps {
  options: SelectOption[];
  placeholder?: string;
  searchable?: boolean;
  label?: string;
  error?: string;
  disabled?: boolean;
  clearable?: boolean;
  className?: string;
  id?: string;
}

interface SingleSelectProps extends SelectBaseProps {
  multiple?: false;
  value: string | null;
  onChange: (value: string | null) => void;
}

interface MultiSelectProps extends SelectBaseProps {
  multiple: true;
  value: string[];
  onChange: (value: string[]) => void;
}

type SelectProps = SingleSelectProps | MultiSelectProps;

function useDropdownPosition(
  triggerRef: React.RefObject<HTMLDivElement | null>
) {
  const [pos, setPos] = useState({ top: 0, left: 0, width: 0 });

  const recalculate = useCallback(() => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    setPos({
      top: rect.bottom + window.scrollY + 4,
      left: rect.left + window.scrollX,
      width: rect.width,
    });
  }, [triggerRef]);

  return { pos, recalculate };
}

// WORKING: Select component (single and multi)
export function Select(props: SelectProps) {
  const {
    options,
    placeholder = 'Select…',
    searchable = false,
    label,
    error,
    disabled = false,
    clearable = false,
    className,
    id: externalId,
  } = props;

  const autoId = useId();
  const inputId = externalId ?? autoId;
  const labelId = `${inputId}-label`;
  const listboxId = `${inputId}-listbox`;

  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState<number>(-1);

  const triggerRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const { pos, recalculate } = useDropdownPosition(triggerRef);

  const isMulti = props.multiple === true;
  const selectedValues: string[] = isMulti
    ? (props.value as string[])
    : props.value
    ? [props.value as string]
    : [];

  const filteredOptions = searchable && search.trim()
    ? options.filter((o) =>
        o.label.toLowerCase().includes(search.toLowerCase())
      )
    : options;

  const openDropdown = useCallback(() => {
    if (disabled) return;
    recalculate();
    setOpen(true);
    setActiveIndex(-1);
  }, [disabled, recalculate]);

  const closeDropdown = useCallback(() => {
    setOpen(false);
    setSearch('');
    setActiveIndex(-1);
  }, []);

  function selectOption(option: SelectOption) {
    if (option.disabled) return;
    if (isMulti) {
      const current = props.value as string[];
      const next = current.includes(option.value)
        ? current.filter((v) => v !== option.value)
        : [...current, option.value];
      (props as MultiSelectProps).onChange(next);
    } else {
      (props as SingleSelectProps).onChange(option.value);
      closeDropdown();
    }
  }

  function clearSelection(e: React.MouseEvent) {
    e.stopPropagation();
    if (isMulti) {
      (props as MultiSelectProps).onChange([]);
    } else {
      (props as SingleSelectProps).onChange(null);
    }
  }

  function handleTriggerKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') {
      e.preventDefault();
      if (!open) openDropdown();
      else setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Escape') {
      closeDropdown();
    }
  }

  function handleListKeyDown(e: KeyboardEvent<HTMLUListElement>) {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIndex >= 0 && filteredOptions[activeIndex]) {
        selectOption(filteredOptions[activeIndex]);
      }
    } else if (e.key === 'Escape') {
      closeDropdown();
    }
  }

  // Scroll active item into view
  useEffect(() => {
    if (!listRef.current || activeIndex < 0) return;
    const item = listRef.current.children[activeIndex] as HTMLElement | undefined;
    item?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex]);

  // Focus search input when opened
  useEffect(() => {
    if (open && searchable && searchRef.current) {
      searchRef.current.focus();
    }
  }, [open, searchable]);

  // Close on outside click
  useEffect(() => {
    if (!open) return;
    function handleClick(e: MouseEvent) {
      if (
        triggerRef.current &&
        !triggerRef.current.contains(e.target as Node)
      ) {
        closeDropdown();
      }
    }
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open, closeDropdown]);

  // Close on scroll/resize
  useEffect(() => {
    if (!open) return;
    const handler = () => { recalculate(); };
    window.addEventListener('scroll', handler, true);
    window.addEventListener('resize', handler);
    return () => {
      window.removeEventListener('scroll', handler, true);
      window.removeEventListener('resize', handler);
    };
  }, [open, recalculate]);

  const selectedLabels = selectedValues
    .map((v) => options.find((o) => o.value === v)?.label)
    .filter(Boolean) as string[];

  const hasClear = clearable && selectedValues.length > 0;

  const dropdown = open ? (
    <div
      style={{ top: pos.top, left: pos.left, width: pos.width }}
      className={cn(
        'fixed z-[9999] rounded-lg border border-gray-200 bg-white shadow-lg',
        'dark:border-gray-700 dark:bg-gray-900',
        'flex flex-col overflow-hidden'
      )}
    >
      {searchable && (
        <div className="border-b border-gray-200 px-3 py-2 dark:border-gray-700">
          <div className="flex items-center gap-2 text-gray-400">
            <Search size={14} aria-hidden="true" />
            <input
              ref={searchRef}
              type="text"
              value={search}
              onChange={(e) => { setSearch(e.target.value); setActiveIndex(-1); }}
              placeholder="Search…"
              aria-label="Search options"
              className={cn(
                'flex-1 bg-transparent text-sm text-gray-900 outline-none',
                'placeholder:text-gray-400 dark:text-gray-100'
              )}
            />
          </div>
        </div>
      )}

      <ul
        ref={listRef}
        id={listboxId}
        role="listbox"
        aria-multiselectable={isMulti}
        aria-labelledby={labelId}
        tabIndex={0}
        onKeyDown={handleListKeyDown}
        className="max-h-60 overflow-y-auto py-1 focus:outline-none"
      >
        {filteredOptions.length === 0 ? (
          <li className="px-3 py-2 text-sm text-gray-400">No options</li>
        ) : (
          filteredOptions.map((option, i) => {
            const isSelected = selectedValues.includes(option.value);
            const isActive = activeIndex === i;
            return (
              <li
                key={option.value}
                id={`${inputId}-option-${option.value}`}
                role="option"
                aria-selected={isSelected}
                aria-disabled={option.disabled}
                onClick={() => selectOption(option)}
                onMouseEnter={() => setActiveIndex(i)}
                className={cn(
                  'flex cursor-pointer items-center gap-2 px-3 py-2 text-sm',
                  'text-gray-700 dark:text-gray-300',
                  isActive && 'bg-teal-50 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300',
                  isSelected && !isActive && 'bg-gray-50 dark:bg-gray-800',
                  option.disabled && 'cursor-not-allowed opacity-50'
                )}
              >
                {option.icon && (
                  <span className="shrink-0">{option.icon}</span>
                )}
                <span className="flex-1">{option.label}</span>
                {isSelected && (
                  <Check size={14} className="shrink-0 text-teal-600 dark:text-teal-400" aria-hidden="true" />
                )}
              </li>
            );
          })
        )}
      </ul>
    </div>
  ) : null;

  return (
    <div className={cn('w-full', className)}>
      {label && (
        <label
          id={labelId}
          htmlFor={inputId}
          className="mb-1.5 block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          {label}
        </label>
      )}

      {/* Trigger */}
      <div
        ref={triggerRef}
        id={inputId}
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-owns={listboxId}
        aria-labelledby={label ? labelId : undefined}
        aria-disabled={disabled}
        tabIndex={disabled ? -1 : 0}
        onClick={() => (open ? closeDropdown() : openDropdown())}
        onKeyDown={handleTriggerKeyDown}
        className={cn(
          'flex min-h-[40px] w-full cursor-pointer items-center gap-2 rounded-lg border px-3 py-2',
          'text-sm text-gray-900 dark:text-gray-100',
          'bg-white dark:bg-gray-800',
          'transition-colors',
          error
            ? 'border-red-400 focus-within:ring-red-400 dark:border-red-500'
            : 'border-gray-300 dark:border-gray-600',
          !disabled && 'hover:border-teal-400 dark:hover:border-teal-500',
          open && !error && 'border-teal-500 ring-2 ring-teal-500/20',
          disabled && 'cursor-not-allowed opacity-60',
          'focus:outline-none'
        )}
      >
        {/* Selected display */}
        <span className="flex flex-1 flex-wrap gap-1 overflow-hidden">
          {selectedLabels.length === 0 ? (
            <span className="text-gray-400">{placeholder}</span>
          ) : isMulti ? (
            selectedLabels.map((lbl) => (
              <span
                key={lbl}
                className="inline-flex items-center rounded-md bg-teal-100 px-2 py-0.5 text-xs font-medium text-teal-800 dark:bg-teal-900/50 dark:text-teal-300"
              >
                {lbl}
              </span>
            ))
          ) : (
            <span>{selectedLabels[0]}</span>
          )}
        </span>

        {/* Clear + chevron */}
        <span className="flex shrink-0 items-center gap-1">
          {hasClear && (
            <button
              type="button"
              aria-label="Clear selection"
              onClick={clearSelection}
              className="rounded p-0.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
            >
              <X size={14} aria-hidden="true" />
            </button>
          )}
          <ChevronDown
            size={16}
            aria-hidden="true"
            className={cn(
              'text-gray-400 transition-transform duration-200',
              open && 'rotate-180'
            )}
          />
        </span>
      </div>

      {error && (
        <p className="mt-1 text-xs text-red-500 dark:text-red-400" role="alert">
          {error}
        </p>
      )}

      {typeof window !== 'undefined' && dropdown
        ? createPortal(dropdown, document.body)
        : null}
    </div>
  );
}

