                'flex-1 bg-transparent text-sm text-gray-900 outline-none',
                'placeholder:text-gray-400 dark:text-gray-100'
              )}
            />
          </div>
        </div>
      )}

      <ul
        ref={listRef}
        id={listboxId}
        role="listbox"
        aria-multiselectable={isMulti}
        aria-labelledby={labelId}
        tabIndex={0}
        onKeyDown={handleListKeyDown}
        className="max-h-60 overflow-y-auto py-1 focus:outline-none"
      >
        {filteredOptions.length === 0 ? (
          <li className="px-3 py-2 text-sm text-gray-400">No options</li>
        ) : (
          filteredOptions.map((option, i) => {
            const isSelected = selectedValues.includes(option.value);
            const isActive = activeIndex === i;
            return (
              <li
                key={option.value}
                id={`${inputId}-option-${option.value}`}
                role="option"
                aria-selected={isSelected}
                aria-disabled={option.disabled}
                onClick={() => selectOption(option)}
                onMouseEnter={() => setActiveIndex(i)}
                className={cn(
                  'flex cursor-pointer items-center gap-2 px-3 py-2 text-sm',
                  'text-gray-700 dark:text-gray-300',
                  isActive && 'bg-teal-50 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300',
                  isSelected && !isActive && 'bg-gray-50 dark:bg-gray-800',
                  option.disabled && 'cursor-not-allowed opacity-50'
                )}
              >
                {option.icon && (
                  <span className="shrink-0">{option.icon}</span>
                )}
                <span className="flex-1">{option.label}</span>
                {isSelected && (
                  <Check size={14} className="shrink-0 text-teal-600 dark:text-teal-400" aria-hidden="true" />
                )}
              </li>
            );
          })
        )}
      </ul>
    </div>
  ) : null;

  return (
    <div className={cn('w-full', className)}>
      {label && (
        <label
          id={labelId}
          htmlFor={inputId}
          className="mb-1.5 block text-sm font-medium text-gray-700 dark:text-gray-300"
        >
          {label}
        </label>
      )}

      {/* Trigger */}
      <div
        ref={triggerRef}
        id={inputId}
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-owns={listboxId}
        aria-labelledby={label ? labelId : undefined}
        aria-disabled={disabled}
        tabIndex={disabled ? -1 : 0}
        onClick={() => (open ? closeDropdown() : openDropdown())}
        onKeyDown={handleTriggerKeyDown}
        className={cn(
          'flex min-h-[40px] w-full cursor-pointer items-center gap-2 rounded-lg border px-3 py-2',
          'text-sm text-gray-900 dark:text-gray-100',
          'bg-white dark:bg-gray-800',
          'transition-colors',
          error
            ? 'border-red-400 focus-within:ring-red-400 dark:border-red-500'
            : 'border-gray-300 dark:border-gray-600',
          !disabled && 'hover:border-teal-400 dark:hover:border-teal-500',
          open && !error && 'border-teal-500 ring-2 ring-teal-500/20',
          disabled && 'cursor-not-allowed opacity-60',
          'focus:outline-none'
        )}
      >
        {/* Selected display */}
        <span className="flex flex-1 flex-wrap gap-1 overflow-hidden">
          {selectedLabels.length === 0 ? (
            <span className="text-gray-400">{placeholder}</span>
          ) : isMulti ? (
            selectedLabels.map((lbl) => (
              <span
                key={lbl}
                className="inline-flex items-center rounded-md bg-teal-100 px-2 py-0.5 text-xs font-medium text-teal-800 dark:bg-teal-900/50 dark:text-teal-300"
              >
                {lbl}
              </span>
            ))
          ) : (
            <span>{selectedLabels[0]}</span>
          )}
        </span>

        {/* Clear + chevron */}
        <span className="flex shrink-0 items-center gap-1">
          {hasClear && (
            <button
              type="button"
              aria-label="Clear selection"
              onClick={clearSelection}
              className="rounded p-0.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
            >
              <X size={14} aria-hidden="true" />
            </button>
          )}
          <ChevronDown
            size={16}
            aria-hidden="true"
            className={cn(
              'text-gray-400 transition-transform duration-200',
              open && 'rotate-180'
            )}
          />
        </span>
      </div>

      {error && (
        <p className="mt-1 text-xs text-red-500 dark:text-red-400" role="alert">
          {error}
        </p>
      )}

      {typeof window !== 'undefined' && dropdown
        ? createPortal(dropdown, document.body)
        : null}
    </div>
  );
}

