/**
 * ISAFlow shared UI component library — barrel export.
 * Import from '@/components/ui' for any shared primitive.
 */

export { Button, buttonVariants } from './Button';
export type { ButtonProps } from './Button';

export { Input, inputVariants } from './Input';
export type { InputProps } from './Input';

export { Badge, badgeVariants } from './Badge';
export type { BadgeProps } from './Badge';

export { Card, CardHeader, CardBody, CardFooter } from './Card';
export type { CardProps } from './Card';

export { Tooltip } from './Tooltip';
export type { TooltipProps, TooltipPosition } from './Tooltip';

export { LoadingSpinner } from './LoadingSpinner';

/**
 * Button — primary interactive element with variants, sizes, icons, and loading state.
 * WORKING: CVA-based variants, Radix Slot asChild support, forward ref.
 */

import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';

const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 rounded-md font-medium',
    'transition-colors duration-150 focus-visible:outline-none',
    'focus-visible:ring-2 focus-visible:ring-offset-2',
    'disabled:pointer-events-none disabled:opacity-50',
    'select-none whitespace-nowrap',
  ],
  {
    variants: {
      variant: {
        primary: [
          'bg-teal-600 text-white',
          'hover:bg-teal-700',
          'focus-visible:ring-teal-500',
          'dark:bg-teal-500 dark:hover:bg-teal-600',
        ],
        secondary: [
          'border border-gray-300 bg-white text-gray-700',
          'hover:bg-gray-50 hover:border-gray-400',
          'focus-visible:ring-teal-500',
          'dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200',
          'dark:hover:bg-gray-700 dark:hover:border-gray-500',
        ],
        ghost: [
          'bg-transparent text-gray-700',
          'hover:bg-gray-100 hover:text-gray-900',
          'focus-visible:ring-teal-500',
          'dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-gray-100',
        ],
        danger: [
          'bg-red-600 text-white',
          'hover:bg-red-700',
          'focus-visible:ring-red-500',
          'dark:bg-red-700 dark:hover:bg-red-800',
        ],
      },
      size: {
        sm: 'h-8 px-3 text-xs',
        md: 'h-9 px-4 text-sm',
        lg: 'h-11 px-6 text-base',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
  leftIcon?: LucideIcon;
  rightIcon?: LucideIcon;
}

// WORKING: Forward ref with asChild (Radix Slot) support
const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      loading = false,
      leftIcon: LeftIcon,
      rightIcon: RightIcon,
      disabled,
      children,
      ...props
    },
    ref
  ) => {
    const Comp = asChild ? Slot : 'button';
    const isDisabled = disabled || loading;

    const spinnerSize = size === 'lg' ? 'md' : 'sm';

    return (
      <Comp
        ref={ref}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        className={cn(buttonVariants({ variant, size }), className)}
        {...props}
      >
        {loading ? (
          <LoadingSpinner size={spinnerSize} />
        ) : (
          LeftIcon && <LeftIcon size={size === 'lg' ? 18 : 16} />
        )}
        {children}
        {!loading && RightIcon && <RightIcon size={size === 'lg' ? 18 : 16} />}
      </Comp>
    );
  }
);

Button.displayName = 'Button';

export { Button, buttonVariants };

/**
 * Modal — accessible modal dialog with portal rendering, focus trap, ESC key,
 * click-outside-to-close, body scroll lock, and smooth animations.
 *
 * Usage:
 *   <Modal open={open} onClose={setOpen.bind(null, false)} title="Edit Item" size="md">
 *     <Modal.Body>...</Modal.Body>
 *     <Modal.Footer>...</Modal.Footer>
 *   </Modal>
 */

import {
  createContext,
  forwardRef,
  useCallback,
  useContext,
  useEffect,
  useRef,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ModalSize = 'sm' | 'md' | 'lg' | 'xl' | 'full';

interface ModalContextValue {
  onClose: () => void;
}

interface ModalProps {
  open: boolean;
  onClose: () => void;
  title?: ReactNode;
  children: ReactNode;
  size?: ModalSize;
  /** Prevent closing when the overlay is clicked */
  disableBackdropClose?: boolean;
}

interface ModalSectionProps {
  children: ReactNode;
  className?: string;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const SIZE_CLASSES: Record<ModalSize, string> = {
  sm: 'max-w-sm',
  md: 'max-w-lg',
  lg: 'max-w-2xl',
  xl: 'max-w-4xl',
  full: 'max-w-full mx-4',
};

const FOCUSABLE =
  'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

const ModalContext = createContext<ModalContextValue | null>(null);

function useModalContext(): ModalContextValue {
  const ctx = useContext(ModalContext);
  if (!ctx) throw new Error('Modal sub-components must be used inside <Modal>');
  return ctx;
}

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

const ModalHeader = forwardRef<HTMLDivElement, ModalSectionProps>(
  ({ children, className }, ref) => {
    const { onClose } = useModalContext();
    return (
      <div
        ref={ref}
        className={cn(
          'flex items-start justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700',
          className
        )}
      >
        <div className="text-lg font-semibold text-gray-900 dark:text-gray-100 pr-4">
          {children}
        </div>
        <button
          type="button"
          onClick={onClose}
          aria-label="Close modal"
          className="shrink-0 p-1 rounded-md text-gray-400 hover:text-gray-600 hover:bg-gray-100 dark:hover:text-gray-200 dark:hover:bg-gray-700 transition-colors"
        >
          <X className="w-5 h-5" />
        </button>
      </div>
    );
  }
);
ModalHeader.displayName = 'Modal.Header';

const ModalBody = forwardRef<HTMLDivElement, ModalSectionProps>(
  ({ children, className }, ref) => (
    <div
      ref={ref}
      className={cn('px-6 py-4 overflow-y-auto flex-1', className)}
    >
      {children}
    </div>
  )
);
ModalBody.displayName = 'Modal.Body';

const ModalFooter = forwardRef<HTMLDivElement, ModalSectionProps>(
  ({ children, className }, ref) => (
    <div
      ref={ref}
      className={cn(
        'flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-200 dark:border-gray-700',
        className
      )}
    >
      {children}
    </div>
  )
);
ModalFooter.displayName = 'Modal.Footer';

// ---------------------------------------------------------------------------
// Root Modal component
// ---------------------------------------------------------------------------

function ModalRoot({
  open,
  onClose,
  title,
  children,
  size = 'md',
  disableBackdropClose = false,
}: ModalProps) {
  const dialogRef = useRef<HTMLDivElement>(null);

  // Lock body scroll
  useEffect(() => {
    if (!open) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [open]);

  // Focus first focusable element on open
  useEffect(() => {
    if (!open || !dialogRef.current) return;
    const el = dialogRef.current.querySelector<HTMLElement>(FOCUSABLE);
    el?.focus();
  }, [open]);

  // ESC to close
  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLDivElement>) => {
      if (e.key === 'Escape') onClose();
    },
    [onClose]
  );

  // Focus trap
  const handleTabKey = useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (e.key !== 'Tab' || !dialogRef.current) return;
      const focusable = Array.from(
        dialogRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)
      );
      if (focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (!first || !last) return;
      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    },
    []
  );

  const handleOverlayClick = useCallback(
    (e: MouseEvent<HTMLDivElement>) => {
      if (!disableBackdropClose && e.target === e.currentTarget) onClose();
    },
    [disableBackdropClose, onClose]
  );

  if (!open) return null;
  if (typeof document === 'undefined') return null;

  return createPortal(
    <ModalContext.Provider value={{ onClose }}>
      {/* Overlay */}
      <div
        role="presentation"
        className="fixed inset-0 z-50 flex items-center justify-center p-4 animate-fadeIn"
        onKeyDown={(e) => {
          handleKeyDown(e);
          handleTabKey(e);
        }}
        onClick={handleOverlayClick}
      >
        {/* Backdrop */}
        <div
          aria-hidden="true"
          className="absolute inset-0 bg-black/50 backdrop-blur-sm"
        />

        {/* Dialog */}
        <div
          ref={dialogRef}
          role="dialog"
          aria-modal="true"
          aria-label={typeof title === 'string' ? title : undefined}
          tabIndex={-1}
          className={cn(
            'relative z-10 w-full bg-white dark:bg-gray-800 rounded-xl shadow-2xl',
            'flex flex-col max-h-[90vh]',
            'animate-in fade-in-0 zoom-in-95 duration-200',
            SIZE_CLASSES[size]
          )}
        >
          {title && <ModalHeader>{title}</ModalHeader>}
          {children}
        </div>
      </div>
    </ModalContext.Provider>,
    document.body
  );
}

// ---------------------------------------------------------------------------
// Compound export
// ---------------------------------------------------------------------------

export const Modal = Object.assign(ModalRoot, {
  Header: ModalHeader,
  Body: ModalBody,
  Footer: ModalFooter,
});

/**
 * Toast — notification system with context provider and useToast() hook.
 *
 * Setup: wrap the app (or _app.tsx) with <ToastProvider>.
 *
 * Usage:
 *   const { toast } = useToast();
 *   toast.success('Saved successfully');
 *   toast.error('Something went wrong', { duration: 8000 });
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';
import {
  CheckCircle,
  AlertCircle,
  AlertTriangle,
  Info,
  X,
} from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface ToastOptions {
  /** Auto-dismiss duration in ms. 0 = never auto-dismiss. Default: 5000 */
  duration?: number;
}

export interface ToastItem extends Required<ToastOptions> {
  id: string;
  type: ToastType;
  message: string;
}

interface ToastContextValue {
  toast: {
    success: (message: string, opts?: ToastOptions) => void;
    error: (message: string, opts?: ToastOptions) => void;
    warning: (message: string, opts?: ToastOptions) => void;
    info: (message: string, opts?: ToastOptions) => void;
  };
  dismiss: (id: string) => void;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_DURATION = 5000;

const TOAST_STYLES: Record<ToastType, { bg: string; icon: ReactNode; text: string }> = {
  success: {
    bg: 'bg-green-50 dark:bg-green-900/30 border-green-200 dark:border-green-700',
    text: 'text-green-800 dark:text-green-200',
    icon: <CheckCircle className="w-5 h-5 text-green-500 shrink-0" />,
  },
  error: {
    bg: 'bg-red-50 dark:bg-red-900/30 border-red-200 dark:border-red-700',
    text: 'text-red-800 dark:text-red-200',
    icon: <AlertCircle className="w-5 h-5 text-red-500 shrink-0" />,
  },
  warning: {
    bg: 'bg-amber-50 dark:bg-amber-900/30 border-amber-200 dark:border-amber-700',
    text: 'text-amber-800 dark:text-amber-200',
    icon: <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0" />,
  },
  info: {
    bg: 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-700',
    text: 'text-blue-800 dark:text-blue-200',
    icon: <Info className="w-5 h-5 text-blue-500 shrink-0" />,
  },
};

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

const ToastContext = createContext<ToastContextValue | null>(null);

// ---------------------------------------------------------------------------
// Single toast tile
// ---------------------------------------------------------------------------

interface ToastTileProps {
  item: ToastItem;
  onDismiss: (id: string) => void;
}

function ToastTile({ item, onDismiss }: ToastTileProps) {
  const style = TOAST_STYLES[item.type];
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (item.duration <= 0) return;
    timerRef.current = setTimeout(() => onDismiss(item.id), item.duration);
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [item.id, item.duration, onDismiss]);

  return (
    <div
      role="alert"
      aria-live="assertive"
      className={cn(
        'flex items-start gap-3 w-80 max-w-full p-4 rounded-lg border shadow-lg',
        'animate-in slide-in-from-right-4 fade-in-0 duration-300',
        style.bg
      )}
    >
      {style.icon}
      <p className={cn('flex-1 text-sm font-medium leading-snug', style.text)}>
        {item.message}
      </p>
      <button
        type="button"
        aria-label="Dismiss notification"
        onClick={() => onDismiss(item.id)}
        className={cn(
          'shrink-0 p-0.5 rounded transition-opacity opacity-60 hover:opacity-100',
          style.text
        )}
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Provider
// ---------------------------------------------------------------------------

let _nextId = 1;
function uid() {
  return `toast-${_nextId++}`;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const add = useCallback(
    (type: ToastType, message: string, opts?: ToastOptions) => {
      const item: ToastItem = {
        id: uid(),
        type,
        message,
        duration: opts?.duration ?? DEFAULT_DURATION,
      };
      setToasts((prev) => [...prev, item]);
    },
    []
  );

  const toast: ToastContextValue['toast'] = {
    success: (msg, opts) => add('success', msg, opts),
    error: (msg, opts) => add('error', msg, opts),
    warning: (msg, opts) => add('warning', msg, opts),
    info: (msg, opts) => add('info', msg, opts),
  };

  return (
    <ToastContext.Provider value={{ toast, dismiss }}>
      {children}
      {mounted &&
        createPortal(
          <div
            aria-label="Notifications"
            className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 items-end"
          >
            {toasts.map((item) => (
              <ToastTile key={item.id} item={item} onDismiss={dismiss} />
            ))}
          </div>,
          document.body
        )}
    </ToastContext.Provider>
  );
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

// // WORKING: Throws a helpful error when used outside provider
export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used inside <ToastProvider>');
  return ctx;
}

/**
 * Select — searchable dropdown with keyboard navigation, portal, multi-select.
 * // WORKING: Portal-based dropdown, full a11y, arrow/enter/escape keyboard nav
 */

import { useState, useRef, useEffect, useCallback, useId, type ReactNode, type KeyboardEvent } from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown, X } from 'lucide-react';
import { cn } from '@/utils/cn';
import { SelectDropdown } from './SelectDropdown';

export interface SelectOption {
  value: string;
  label: string;
  icon?: ReactNode;
  disabled?: boolean;
}

interface SelectBaseProps {
  options: SelectOption[];
  placeholder?: string;
  searchable?: boolean;
  label?: string;
  error?: string;
  disabled?: boolean;
  clearable?: boolean;
  className?: string;
  id?: string;
}

interface SingleSelectProps extends SelectBaseProps {
  multiple?: false;
  value: string | null;
  onChange: (value: string | null) => void;
}

interface MultiSelectProps extends SelectBaseProps {
  multiple: true;
  value: string[];
  onChange: (value: string[]) => void;
}

export type SelectProps = SingleSelectProps | MultiSelectProps;

// WORKING: Select component (single and multi-select)
export function Select(props: SelectProps) {
  const { options, placeholder = 'Select…', searchable = false, label, error, disabled = false, clearable = false, className, id: externalId } = props;

  const autoId = useId();
  const inputId = externalId ?? autoId;
  const labelId = `${inputId}-label`;
  const listboxId = `${inputId}-listbox`;

  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [activeIndex, setActiveIndex] = useState(-1);
  const [pos, setPos] = useState({ top: 0, left: 0, width: 0 });

  const triggerRef = useRef<HTMLDivElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const isMulti = props.multiple === true;
  const selectedValues: string[] = isMulti ? (props.value as string[]) : props.value ? [props.value as string] : [];
  const filteredOptions = searchable && search.trim() ? options.filter((o) => o.label.toLowerCase().includes(search.toLowerCase())) : options;

  const recalculate = useCallback(() => {
    if (!triggerRef.current) return;
    const r = triggerRef.current.getBoundingClientRect();
    setPos({ top: r.bottom + window.scrollY + 4, left: r.left + window.scrollX, width: r.width });
  }, []);

  const closeDropdown = useCallback(() => { setOpen(false); setSearch(''); setActiveIndex(-1); }, []);
  const openDropdown = useCallback(() => { if (disabled) return; recalculate(); setOpen(true); setActiveIndex(-1); }, [disabled, recalculate]);

  function selectOption(option: SelectOption) {
    if (option.disabled) return;
    if (isMulti) {
      const cur = props.value as string[];
      (props as MultiSelectProps).onChange(cur.includes(option.value) ? cur.filter((v) => v !== option.value) : [...cur, option.value]);
    } else {
      (props as SingleSelectProps).onChange(option.value);
      closeDropdown();
    }
  }

  function clearSelection(e: React.MouseEvent) {
    e.stopPropagation();
    isMulti ? (props as MultiSelectProps).onChange([]) : (props as SingleSelectProps).onChange(null);
  }

  function handleTriggerKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown') { e.preventDefault(); open ? setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1)) : openDropdown(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIndex((i) => Math.max(i - 1, 0)); }
    else if (e.key === 'Escape') closeDropdown();
  }

  function handleListKeyDown(e: KeyboardEvent<HTMLUListElement>) {
    if (e.key === 'ArrowDown') { e.preventDefault(); setActiveIndex((i) => Math.min(i + 1, filteredOptions.length - 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setActiveIndex((i) => Math.max(i - 1, 0)); }
    else if (e.key === 'Enter') { e.preventDefault(); if (activeIndex >= 0 && filteredOptions[activeIndex]) selectOption(filteredOptions[activeIndex]); }
    else if (e.key === 'Escape') closeDropdown();
  }

  useEffect(() => {
    if (!listRef.current || activeIndex < 0) return;
    (listRef.current.children[activeIndex] as HTMLElement | undefined)?.scrollIntoView({ block: 'nearest' });
  }, [activeIndex]);

  useEffect(() => { if (open && searchable && searchRef.current) searchRef.current.focus(); }, [open, searchable]);

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => { if (triggerRef.current && !triggerRef.current.contains(e.target as Node)) closeDropdown(); };
    document.addEventListener('mousedown', onClick);
    return () => document.removeEventListener('mousedown', onClick);
  }, [open, closeDropdown]);

  useEffect(() => {
    if (!open) return;
    window.addEventListener('scroll', recalculate, true);
    window.addEventListener('resize', recalculate);
    return () => { window.removeEventListener('scroll', recalculate, true); window.removeEventListener('resize', recalculate); };
  }, [open, recalculate]);

  const selectedLabels = selectedValues.map((v) => options.find((o) => o.value === v)?.label).filter(Boolean) as string[];
  const hasClear = clearable && selectedValues.length > 0;

  return (
    <div className={cn('w-full', className)}>
      {label && (
        <label id={labelId} htmlFor={inputId} className="mb-1.5 block text-sm font-medium text-gray-700 dark:text-gray-300">
          {label}
        </label>
      )}
      <div
        ref={triggerRef}
        id={inputId}
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-owns={listboxId}
        aria-labelledby={label ? labelId : undefined}
        aria-disabled={disabled}
        tabIndex={disabled ? -1 : 0}
        onClick={() => (open ? closeDropdown() : openDropdown())}
        onKeyDown={handleTriggerKeyDown}
        className={cn(
          'flex min-h-[40px] w-full cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-sm transition-colors focus:outline-none',
          'bg-white text-gray-900 dark:bg-gray-800 dark:text-gray-100',
          error ? 'border-red-400 dark:border-red-500' : 'border-gray-300 dark:border-gray-600',
          !disabled && 'hover:border-teal-400 dark:hover:border-teal-500',
          open && !error && 'border-teal-500 ring-2 ring-teal-500/20',
          disabled && 'cursor-not-allowed opacity-60'
        )}
      >
        <span className="flex flex-1 flex-wrap gap-1 overflow-hidden">
          {selectedLabels.length === 0 ? (
            <span className="text-gray-400">{placeholder}</span>
          ) : isMulti ? (
            selectedLabels.map((lbl) => (
              <span key={lbl} className="inline-flex items-center rounded-md bg-teal-100 px-2 py-0.5 text-xs font-medium text-teal-800 dark:bg-teal-900/50 dark:text-teal-300">{lbl}</span>
            ))
          ) : (
            <span>{selectedLabels[0]}</span>
          )}
        </span>
        <span className="flex shrink-0 items-center gap-1">
          {hasClear && (
            <button type="button" aria-label="Clear selection" onClick={clearSelection} className="rounded p-0.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
              <X size={14} aria-hidden="true" />
            </button>
          )}
          <ChevronDown size={16} aria-hidden="true" className={cn('text-gray-400 transition-transform duration-200', open && 'rotate-180')} />
        </span>
      </div>
      {error && <p className="mt-1 text-xs text-red-500 dark:text-red-400" role="alert">{error}</p>}
      {typeof window !== 'undefined' && open
        ? createPortal(
            <SelectDropdown
              options={filteredOptions}
              selectedValues={selectedValues}
              activeIndex={activeIndex}
              searchable={searchable}
              search={search}
              listboxId={listboxId}
              labelId={labelId}
              inputId={inputId}
              isMulti={isMulti}
              pos={pos}
              searchRef={searchRef}
              listRef={listRef}
              onSearchChange={(v) => { setSearch(v); setActiveIndex(-1); }}
              onSelect={selectOption}
              onActiveChange={setActiveIndex}
              onKeyDown={handleListKeyDown}
            />,
            document.body
          )
        : null}
    </div>
  );
}

/**
 * SelectDropdown — internal portal dropdown panel for the Select component.
 * Not exported from the public component library — used only by Select.tsx.
 */

import React, { type KeyboardEvent, type RefObject } from 'react';
import { Check, Search } from 'lucide-react';
import { cn } from '@/utils/cn';
import type { SelectOption } from './Select';

interface SelectDropdownProps {
  options: SelectOption[];
  selectedValues: string[];
  activeIndex: number;
  searchable: boolean;
  search: string;
  listboxId: string;
  labelId: string;
  inputId: string;
  isMulti: boolean;
  pos: { top: number; left: number; width: number };
  searchRef: RefObject<HTMLInputElement>;
  listRef: RefObject<HTMLUListElement>;
  onSearchChange: (value: string) => void;
  onSelect: (option: SelectOption) => void;
  onActiveChange: (index: number) => void;
  onKeyDown: (e: KeyboardEvent<HTMLUListElement>) => void;
}

export function SelectDropdown({
  options,
  selectedValues,
  activeIndex,
  searchable,
  search,
  listboxId,
  labelId,
  inputId,
  isMulti,
  pos,
  searchRef,
  listRef,
  onSearchChange,
  onSelect,
  onActiveChange,
  onKeyDown,
}: SelectDropdownProps) {
  return (
    <div
      style={{ top: pos.top, left: pos.left, width: pos.width }}
      className={cn(
        'fixed z-[9999] flex flex-col overflow-hidden rounded-lg',
        'border border-gray-200 bg-white shadow-lg',
        'dark:border-gray-700 dark:bg-gray-900'
      )}
    >
      {searchable && (
        <div className="border-b border-gray-200 px-3 py-2 dark:border-gray-700">
          <div className="flex items-center gap-2 text-gray-400">
            <Search size={14} aria-hidden="true" />
            <input
              ref={searchRef as React.RefObject<HTMLInputElement>}
              type="text"
              value={search}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="Search…"
              aria-label="Search options"
              className="flex-1 bg-transparent text-sm text-gray-900 outline-none placeholder:text-gray-400 dark:text-gray-100"
            />
          </div>
        </div>
      )}

      <ul
        ref={listRef as React.RefObject<HTMLUListElement>}
        id={listboxId}
        role="listbox"
        aria-multiselectable={isMulti}
        aria-labelledby={labelId}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className="max-h-60 overflow-y-auto py-1 focus:outline-none"
      >
        {options.length === 0 ? (
          <li className="px-3 py-2 text-sm text-gray-400">No options</li>
        ) : (
          options.map((option, i) => {
            const isSelected = selectedValues.includes(option.value);
            const isActive = activeIndex === i;
            return (
              <li
                key={option.value}
                id={`${inputId}-option-${option.value}`}
                role="option"
                aria-selected={isSelected}
                aria-disabled={option.disabled}
                onClick={() => onSelect(option)}
                onMouseEnter={() => onActiveChange(i)}
                className={cn(
                  'flex cursor-pointer items-center gap-2 px-3 py-2 text-sm',
                  'text-gray-700 dark:text-gray-300',
                  isActive && 'bg-teal-50 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300',
                  isSelected && !isActive && 'bg-gray-50 dark:bg-gray-800',
                  option.disabled && 'cursor-not-allowed opacity-50'
                )}
              >
                {option.icon && <span className="shrink-0">{option.icon}</span>}
                <span className="flex-1">{option.label}</span>
                {isSelected && (
                  <Check
                    size={14}
                    aria-hidden="true"
                    className="shrink-0 text-teal-600 dark:text-teal-400"
                  />
                )}
              </li>
            );
          })
        )}
      </ul>
    </div>
  );
}

/**
 * Breadcrumb — accessible breadcrumb navigation with responsive collapsing.
 *
 * Usage:
 *   <Breadcrumb
 *     items={[
 *       { label: 'Accounting', href: '/accounting' },
 *       { label: 'Invoices', href: '/accounting/customer-invoices' },
 *       { label: 'INV-0042' },
 *     ]}
 *   />
 */

import { useState } from 'react';
import Link from 'next/link';
import { ChevronRight, MoreHorizontal } from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type BreadcrumbSeparator = 'chevron' | 'slash';

export interface BreadcrumbItem {
  label: string;
  href?: string;
  onClick?: () => void;
}

interface BreadcrumbProps {
  items: BreadcrumbItem[];
  separator?: BreadcrumbSeparator;
  className?: string;
  /** Max items shown before collapsing. 0 = no collapse. Default: 4 */
  maxVisible?: number;
}

// ---------------------------------------------------------------------------
// Separator
// ---------------------------------------------------------------------------

function Separator({ type }: { type: BreadcrumbSeparator }) {
  if (type === 'chevron') {
    return (
      <ChevronRight
        aria-hidden="true"
        className="w-4 h-4 text-gray-400 dark:text-gray-500 shrink-0"
      />
    );
  }
  return (
    <span aria-hidden="true" className="text-gray-400 dark:text-gray-500 select-none">
      /
    </span>
  );
}

// ---------------------------------------------------------------------------
// Item renderers
// ---------------------------------------------------------------------------

function BreadcrumbLink({ item }: { item: BreadcrumbItem }) {
  const base =
    'text-sm text-gray-500 dark:text-gray-400 hover:text-teal-600 dark:hover:text-teal-400 transition-colors truncate max-w-[10rem]';

  if (item.href) {
    return (
      <Link href={item.href} className={base}>
        {item.label}
      </Link>
    );
  }
  if (item.onClick) {
    return (
      <button type="button" onClick={item.onClick} className={cn(base, 'focus:outline-none')}>
        {item.label}
      </button>
    );
  }
  // No href/onClick — render as plain text (fallback)
  return <span className={base}>{item.label}</span>;
}

function BreadcrumbCurrent({ label }: { label: string }) {
  return (
    <span
      aria-current="page"
      className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate max-w-[12rem]"
    >
      {label}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

// // WORKING: Collapsing handled via local state; no router dependency
export function Breadcrumb({
  items,
  separator = 'chevron',
  className,
  maxVisible = 4,
}: BreadcrumbProps) {
  const [expanded, setExpanded] = useState(false);

  if (items.length === 0) return null;

  const shouldCollapse = maxVisible > 0 && !expanded && items.length > maxVisible;

  // Build visible items: always show first + last, collapse the middle
  let visibleItems: (BreadcrumbItem | null)[] = items;
  if (shouldCollapse) {
    // Show first, ellipsis placeholder, then last (maxVisible - 2) items
    const tail = items.slice(-(maxVisible - 1));
    visibleItems = [items[0] ?? null, null, ...tail];
  }

  const lastIndex = visibleItems.length - 1;

  return (
    <nav aria-label="Breadcrumb" className={cn('flex items-center', className)}>
      <ol className="flex items-center flex-wrap gap-1">
        {visibleItems.map((item, idx) => {
          const isLast = idx === lastIndex;

          if (item === null) {
            // Ellipsis
            return (
              <li key="ellipsis" className="flex items-center gap-1">
                <Separator type={separator} />
                <button
                  type="button"
                  aria-label="Show all breadcrumbs"
                  onClick={() => setExpanded(true)}
                  className="p-0.5 rounded text-gray-400 hover:text-teal-600 dark:hover:text-teal-400 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500"
                >
                  <MoreHorizontal className="w-4 h-4" />
                </button>
              </li>
            );
          }

          return (
            <li key={`${item.label}-${idx}`} className="flex items-center gap-1">
              {idx > 0 && <Separator type={separator} />}
              {isLast ? (
                <BreadcrumbCurrent label={item.label} />
              ) : (
                <BreadcrumbLink item={item} />
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

/**
 * Drawer — slide-in panel from the right side of the screen.
 * // WORKING: Portal-based, ESC key, backdrop click-to-close, smooth animation
 */

import { useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { cn } from '@/utils/cn';

type DrawerWidth = 'sm' | 'md' | 'lg' | 'xl';

interface DrawerProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  width?: DrawerWidth;
  className?: string;
}

const WIDTH_CLASSES: Record<DrawerWidth, string> = {
  sm: 'w-80',    // 320px
  md: 'w-[480px]',
  lg: 'w-[640px]',
  xl: 'w-[800px]',
};

// WORKING: Drawer component with portal rendering
export function Drawer({
  open,
  onClose,
  title,
  children,
  width = 'md',
  className,
}: DrawerProps) {
  const previouslyFocused = useRef<Element | null>(null);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    },
    [onClose]
  );

  useEffect(() => {
    if (open) {
      previouslyFocused.current = document.activeElement;
      document.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
    } else {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
      if (previouslyFocused.current instanceof HTMLElement) {
        previouslyFocused.current.focus();
      }
    }
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
    };
  }, [open, handleKeyDown]);

  if (typeof window === 'undefined') return null;

  const drawer = (
    <div
      aria-modal="true"
      aria-label={title}
      role="dialog"
      className={cn(
        'fixed inset-0 z-50 flex justify-end',
        !open && 'pointer-events-none'
      )}
    >
      {/* Backdrop */}
      <div
        aria-hidden="true"
        onClick={onClose}
        className={cn(
          'absolute inset-0 bg-black/50 transition-opacity duration-300',
          open ? 'opacity-100' : 'opacity-0'
        )}
      />

      {/* Panel */}
      <div
        className={cn(
          'relative flex h-full flex-col bg-white shadow-xl',
          'dark:bg-gray-900',
          'transition-transform duration-300 ease-in-out',
          WIDTH_CLASSES[width],
          open ? 'translate-x-0' : 'translate-x-full',
          className
        )}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-gray-200 px-6 py-4 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
            {title}
          </h2>
          <button
            type="button"
            aria-label="Close drawer"
            onClick={onClose}
            className={cn(
              'rounded-md p-1 text-gray-400 transition-colors',
              'hover:bg-gray-100 hover:text-gray-600',
              'dark:hover:bg-gray-800 dark:hover:text-gray-300',
              'focus:outline-none focus:ring-2 focus:ring-teal-500'
            )}
          >
            <X size={20} aria-hidden="true" />
          </button>
        </div>

        {/* Scrollable content */}
        <div className="flex-1 overflow-y-auto px-6 py-4">{children}</div>
      </div>
    </div>
  );

  return createPortal(drawer, document.body);
}

/**
 * Input — form text field with label, error/helper text, icon slots, and size variants.
 * WORKING: Forward ref, aria attributes, CVA-based styling.
 */

import * as React from 'react';
import { cva, type VariantProps } from 'class-variance-authority';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';

const inputVariants = cva(
  [
    'w-full rounded-md border bg-white font-normal text-gray-900 placeholder-gray-400',
    'transition-colors duration-150 outline-none',
    'focus:ring-2 focus:ring-offset-0',
    'disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-gray-50',
    'dark:bg-gray-800 dark:text-gray-100 dark:placeholder-gray-500',
    'dark:disabled:bg-gray-900',
  ],
  {
    variants: {
      inputVariant: {
        default: [
          'border-gray-300 focus:border-teal-500 focus:ring-teal-500/20',
          'dark:border-gray-600 dark:focus:border-teal-400',
        ],
        error: [
          'border-red-400 focus:border-red-500 focus:ring-red-500/20',
          'dark:border-red-500',
        ],
        success: [
          'border-green-400 focus:border-green-500 focus:ring-green-500/20',
          'dark:border-green-500',
        ],
      },
      size: {
        sm: 'h-8 px-2.5 text-xs',
        md: 'h-9 px-3 text-sm',
        lg: 'h-11 px-4 text-base',
      },
    },
    defaultVariants: {
      inputVariant: 'default',
      size: 'md',
    },
  }
);

export interface InputProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'>,
    VariantProps<typeof inputVariants> {
  label?: string;
  error?: string;
  helperText?: string;
  leftIcon?: LucideIcon;
  rightIcon?: LucideIcon;
}

// WORKING: Forward ref input with accessible label + error message linkage
const Input = React.forwardRef<HTMLInputElement, InputProps>(
  (
    {
      className,
      inputVariant,
      size,
      label,
      error,
      helperText,
      leftIcon: LeftIcon,
      rightIcon: RightIcon,
      id,
      disabled,
      ...props
    },
    ref
  ) => {
    const generatedId = React.useId();
    const inputId = id ?? generatedId;
    const errorId = `${inputId}-error`;
    const helperId = `${inputId}-helper`;

    const resolvedVariant = error ? 'error' : inputVariant;
    const iconSize = size === 'lg' ? 18 : size === 'sm' ? 14 : 16;
    const hasLeftIcon = Boolean(LeftIcon);
    const hasRightIcon = Boolean(RightIcon);

    return (
      <div className="flex flex-col gap-1">
        {label && (
          <label
            htmlFor={inputId}
            className="text-sm font-medium text-gray-700 dark:text-gray-300"
          >
            {label}
          </label>
        )}

        <div className="relative flex items-center">
          {LeftIcon && (
            <span className="pointer-events-none absolute left-2.5 flex items-center text-gray-400 dark:text-gray-500">
              <LeftIcon size={iconSize} />
            </span>
          )}

          <input
            ref={ref}
            id={inputId}
            disabled={disabled}
            aria-invalid={Boolean(error)}
            aria-describedby={
              [error ? errorId : null, helperText ? helperId : null]
                .filter(Boolean)
                .join(' ') || undefined
            }
            className={cn(
              inputVariants({ inputVariant: resolvedVariant, size }),
              hasLeftIcon && (size === 'lg' ? 'pl-10' : size === 'sm' ? 'pl-8' : 'pl-9'),
              hasRightIcon && (size === 'lg' ? 'pr-10' : size === 'sm' ? 'pr-8' : 'pr-9'),
              className
            )}
            {...props}
          />

          {RightIcon && (
            <span className="pointer-events-none absolute right-2.5 flex items-center text-gray-400 dark:text-gray-500">
              <RightIcon size={iconSize} />
            </span>
          )}
        </div>

        {error && (
          <p id={errorId} role="alert" className="text-xs text-red-600 dark:text-red-400">
            {error}
          </p>
        )}

        {!error && helperText && (
          <p id={helperId} className="text-xs text-gray-500 dark:text-gray-400">
            {helperText}
          </p>
        )}
      </div>
    );
  }
);

Input.displayName = 'Input';

export { Input, inputVariants };

