/**
 * Tabs — accessible horizontal tab bar with optional URL sync, count badges,
 * and two visual variants: 'underline' and 'pill'.
 *
 * Usage (controlled, no URL sync):
 *   <Tabs
 *     tabs={[
 *       { id: 'all', label: 'All', count: 42 },
 *       { id: 'draft', label: 'Draft', count: 3, icon: FileText },
 *     ]}
 *     activeTab="all"
 *     onChange={setActiveTab}
 *   />
 *
 * Usage (URL sync via ?tab= query param):
 *   <Tabs tabs={tabs} urlParam="tab" />
 */

import { useCallback, type ReactNode } from 'react';
import { useRouter } from 'next/router';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type TabVariant = 'underline' | 'pill';

export interface TabDefinition {
  id: string;
  label: string;
  /** Optional numeric badge shown next to the label */
  count?: number;
  /** Optional Lucide icon shown before the label */
  icon?: LucideIcon;
  /** Disable this tab */
  disabled?: boolean;
}

interface TabsBaseProps {
  tabs: TabDefinition[];
  variant?: TabVariant;
  className?: string;
  /** ARIA label for the tablist */
  'aria-label'?: string;
}

/** Controlled mode — caller manages activeTab state */
interface TabsControlledProps extends TabsBaseProps {
  activeTab: string;
  onChange: (id: string) => void;
  urlParam?: never;
}

/** URL-sync mode — reads/writes Next.js router query param */
interface TabsUrlProps extends TabsBaseProps {
  urlParam: string;
  activeTab?: string;
  onChange?: (id: string) => void;
}

type TabsProps = TabsControlledProps | TabsUrlProps;

// ---------------------------------------------------------------------------
// Count badge
// ---------------------------------------------------------------------------

function CountBadge({ count, active }: { count: number; active: boolean }) {
  return (
    <span
      className={cn(
        'ml-1.5 inline-flex items-center justify-center rounded-full px-1.5 py-0.5 text-xs font-medium leading-none tabular-nums',
        active
          ? 'bg-teal-100 text-teal-700 dark:bg-teal-800/40 dark:text-teal-300'
          : 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400'
      )}
    >
      {count}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Tab button
// ---------------------------------------------------------------------------

interface TabButtonProps {
  tab: TabDefinition;
  active: boolean;
  variant: TabVariant;
  onClick: () => void;
}

function TabButton({ tab, active, variant, onClick }: TabButtonProps) {
  const Icon = tab.icon;

  const underlineClasses = cn(
    'relative inline-flex items-center gap-1.5 px-1 pb-3 pt-1 text-sm font-medium border-b-2 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500 focus-visible:ring-offset-1',
    active
      ? 'border-teal-600 text-teal-600 dark:border-teal-400 dark:text-teal-400'
      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-200 dark:hover:border-gray-600',
    tab.disabled && 'cursor-not-allowed opacity-50 pointer-events-none'
  );

  const pillClasses = cn(
    'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500',
    active
      ? 'bg-teal-600 text-white dark:bg-teal-500'
      : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900 dark:text-gray-400 dark:hover:bg-gray-700 dark:hover:text-gray-100',
    tab.disabled && 'cursor-not-allowed opacity-50 pointer-events-none'
  );

  return (
    <button
      type="button"
      role="tab"
      id={`tab-${tab.id}`}
      aria-selected={active}
      aria-controls={`panel-${tab.id}`}
      aria-disabled={tab.disabled}
      disabled={tab.disabled}
      tabIndex={active ? 0 : -1}
      onClick={onClick}
      className={variant === 'underline' ? underlineClasses : pillClasses}
    >
      {Icon && <Icon className="w-4 h-4 shrink-0" aria-hidden="true" />}
      {tab.label}
      {tab.count !== undefined && <CountBadge count={tab.count} active={active} />}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Root component
// ---------------------------------------------------------------------------

// // WORKING: URL sync reads from router.query; shallow push keeps scroll position
export function Tabs(props: TabsProps): ReactNode {
  const router = useRouter();

  // Resolve active tab
  let activeTab: string;
  if ('urlParam' in props && props.urlParam) {
    const fromUrl = router.query[props.urlParam];
    activeTab =
      props.activeTab ??
      (typeof fromUrl === 'string' ? fromUrl : null) ??
      props.tabs[0]?.id ??
      '';
  } else {
    activeTab = (props as TabsControlledProps).activeTab ?? props.tabs[0]?.id ?? '';
  }

  const handleChange = useCallback(
    (id: string) => {
      if ('urlParam' in props && props.urlParam) {
        void router.push(
          { query: { ...router.query, [props.urlParam]: id } },
          undefined,
          { shallow: true }
        );
        props.onChange?.(id);
      } else {
        (props as TabsControlledProps).onChange(id);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [router, props]
  );

  const { variant = 'underline', className } = props;

  return (
    <div
      role="tablist"
      aria-label={props['aria-label'] ?? 'Tabs'}
      className={cn(
        'flex',
        variant === 'underline'
          ? 'gap-6 border-b border-gray-200 dark:border-gray-700'
          : 'gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl w-fit',
        className
      )}
    >
      {props.tabs.map((tab) => (
        <TabButton
          key={tab.id}
          tab={tab}
          active={tab.id === activeTab}
          variant={variant}
          onClick={() => handleChange(tab.id)}
        />
      ))}
    </div>
  );
}

/**
 * ProgressBar — linear progress indicator with label and percentage display.
 * // WORKING: Smooth CSS transition on value change, configurable colors and sizes
 */

import { cn } from '@/utils/cn';

type ProgressColor = 'teal' | 'green' | 'amber' | 'red' | 'blue';
type ProgressSize = 'sm' | 'md' | 'lg';

interface ProgressBarProps {
  value: number;
  label?: string;
  showPercentage?: boolean;
  size?: ProgressSize;
  color?: ProgressColor;
  className?: string;
  id?: string;
}

const SIZE_CLASSES: Record<ProgressSize, string> = {
  sm: 'h-1.5',
  md: 'h-2.5',
  lg: 'h-4',
};

const COLOR_CLASSES: Record<ProgressColor, string> = {
  teal: 'bg-teal-500',
  green: 'bg-green-500',
  amber: 'bg-amber-500',
  red: 'bg-red-500',
  blue: 'bg-blue-500',
};

function clampValue(value: number): number {
  return Math.min(100, Math.max(0, value));
}

// WORKING: ProgressBar component
export function ProgressBar({
  value,
  label,
  showPercentage = false,
  size = 'md',
  color = 'teal',
  className,
  id,
}: ProgressBarProps) {
  const clamped = clampValue(value);
  const labelId = id ?? (label ? `progress-label-${label.replace(/\s+/g, '-').toLowerCase()}` : undefined);

  return (
    <div className={cn('w-full', className)}>
      {/* Label row */}
      {(label || showPercentage) && (
        <div className="mb-1.5 flex items-center justify-between gap-2">
          {label && (
            <span
              id={labelId}
              className="text-sm font-medium text-gray-700 dark:text-gray-300"
            >
              {label}
            </span>
          )}
          {showPercentage && (
            <span
              aria-hidden="true"
              className="text-sm tabular-nums text-gray-500 dark:text-gray-400"
            >
              {Math.round(clamped)}%
            </span>
          )}
        </div>
      )}

      {/* Track */}
      <div
        role="progressbar"
        aria-valuenow={clamped}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-labelledby={labelId}
        aria-label={label ?? `${Math.round(clamped)}% complete`}
        className={cn(
          'w-full overflow-hidden rounded-full bg-gray-200 dark:bg-gray-700',
          SIZE_CLASSES[size]
        )}
      >
        {/* Fill */}
        <div
          style={{ width: `${clamped}%` }}
          className={cn(
            'h-full rounded-full transition-[width] duration-500 ease-out',
            COLOR_CLASSES[color]
          )}
        />
      </div>
    </div>
  );
}

/**
 * Skeleton — loading placeholder shapes with shimmer animation.
 * // WORKING: Uses tailwind shimmer keyframe already defined in tailwind.config.mjs
 */

import { cn } from '@/utils/cn';

type SkeletonVariant = 'text' | 'heading' | 'avatar' | 'card' | 'table-row';

interface SkeletonProps {
  variant?: SkeletonVariant;
  width?: string;
  height?: string;
  count?: number;
  className?: string;
}

interface SkeletonGroupProps {
  children: React.ReactNode;
  className?: string;
}

// Shimmer base — uses the 'shimmer' animation from tailwind config
const SHIMMER_BASE = [
  'animate-shimmer',
  'bg-[length:200%_100%]',
  'bg-gradient-to-r',
  'from-gray-200 via-gray-100 to-gray-200',
  'dark:from-gray-700 dark:via-gray-600 dark:to-gray-700',
  'rounded',
].join(' ');

function SingleSkeleton({
  variant = 'text',
  width,
  height,
  className,
}: Omit<SkeletonProps, 'count'>) {
  if (variant === 'table-row') {
    return (
      <div className={cn('flex gap-4', className)}>
        {[40, 25, 20, 15].map((pct, i) => (
          <div
            key={i}
            aria-hidden="true"
            style={{ width: `${pct}%` }}
            className={cn(SHIMMER_BASE, 'h-4 rounded')}
          />
        ))}
      </div>
    );
  }

  const variantClasses: Record<Exclude<SkeletonVariant, 'table-row'>, string> = {
    text: 'h-4 w-full rounded',
    heading: 'h-7 w-3/4 rounded',
    avatar: 'h-10 w-10 rounded-full',
    card: 'h-32 w-full rounded-lg',
  };

  const resolvedVariant = variant as Exclude<SkeletonVariant, 'table-row'>;

  return (
    <div
      aria-hidden="true"
      style={{ width, height }}
      className={cn(SHIMMER_BASE, variantClasses[resolvedVariant], className)}
    />
  );
}

// WORKING: Skeleton component with multiple variants
export function Skeleton({
  variant = 'text',
  width,
  height,
  count = 1,
  className,
}: SkeletonProps) {
  if (count === 1) {
    return (
      <SingleSkeleton
        variant={variant}
        width={width}
        height={height}
        className={className}
      />
    );
  }

  return (
    <>
      {Array.from({ length: count }, (_, i) => (
        <SingleSkeleton
          key={i}
          variant={variant}
          width={width}
          height={height}
          className={className}
        />
      ))}
    </>
  );
}

// WORKING: Skeleton.Group — wraps multiple skeletons with consistent spacing
function SkeletonGroup({ children, className }: SkeletonGroupProps) {
  return (
    <div className={cn('flex flex-col gap-3', className)}>{children}</div>
  );
}

Skeleton.Group = SkeletonGroup;

/**
 * Avatar — user/company avatar with image or deterministic initials fallback.
 * // WORKING: Initials derived from name, background color hashed from name string
 */

import { cn } from '@/utils/cn';

type AvatarSize = 'sm' | 'md' | 'lg' | 'xl';
type AvatarStatus = 'online' | 'offline' | 'busy';

interface AvatarProps {
  src?: string;
  name?: string;
  size?: AvatarSize;
  status?: AvatarStatus;
  className?: string;
  alt?: string;
}

const SIZE_CLASSES: Record<AvatarSize, string> = {
  sm: 'h-8 w-8 text-xs',
  md: 'h-10 w-10 text-sm',
  lg: 'h-12 w-12 text-base',
  xl: 'h-16 w-16 text-lg',
};

const STATUS_DOT_SIZE: Record<AvatarSize, string> = {
  sm: 'h-2 w-2',
  md: 'h-2.5 w-2.5',
  lg: 'h-3 w-3',
  xl: 'h-3.5 w-3.5',
};

const STATUS_COLOR: Record<AvatarStatus, string> = {
  online: 'bg-green-500',
  offline: 'bg-gray-400',
  busy: 'bg-amber-500',
};

// Palette of accessible background colors for initials avatars
const PALETTE = [
  'bg-teal-600',
  'bg-blue-600',
  'bg-violet-600',
  'bg-rose-600',
  'bg-amber-600',
  'bg-emerald-600',
  'bg-indigo-600',
  'bg-pink-600',
  'bg-cyan-600',
  'bg-orange-600',
];

function getInitials(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  if (words.length === 0) return '?';
  const first = words[0] as string;
  if (words.length === 1) return first.charAt(0).toUpperCase();
  const last = words[words.length - 1] as string;
  return `${first.charAt(0)}${last.charAt(0)}`.toUpperCase();
}

function getColorFromName(name: string): string {
  let hash = 0;
  for (let i = 0; i < name.length; i++) {
    hash = name.charCodeAt(i) + ((hash << 5) - hash);
    hash |= 0; // convert to 32-bit int
  }
  const index = Math.abs(hash) % PALETTE.length;
  return PALETTE[index] ?? 'bg-teal-600';
}

// WORKING: Avatar component
export function Avatar({
  src,
  name = '',
  size = 'md',
  status,
  className,
  alt,
}: AvatarProps) {
  const initials = getInitials(name);
  const bgColor = getColorFromName(name || 'default');
  const displayAlt = alt ?? name ?? 'Avatar';

  return (
    <div className={cn('relative inline-flex shrink-0', className)}>
      <div
        className={cn(
          'flex items-center justify-center rounded-full overflow-hidden',
          SIZE_CLASSES[size]
        )}
      >
        {src ? (
          <img
            src={src}
            alt={displayAlt}
            className="h-full w-full object-cover"
          />
        ) : (
          <div
            aria-label={displayAlt}
            className={cn(
              'flex h-full w-full items-center justify-center rounded-full font-semibold text-white',
              bgColor
            )}
          >
            {initials}
          </div>
        )}
      </div>

      {status && (
        <span
          aria-label={`Status: ${status}`}
          className={cn(
            'absolute bottom-0 right-0 block rounded-full ring-2 ring-white dark:ring-gray-900',
            STATUS_DOT_SIZE[size],
            STATUS_COLOR[status]
          )}
        />
      )}
    </div>
  );
}

/**
 * EmptyState — centered empty-state block with an icon, title, description,
 * and optional primary / secondary action buttons.
 *
 * Usage:
 *   <EmptyState
 *     icon={FileText}
 *     title="No invoices yet"
 *     description="Create your first invoice to get started."
 *     primaryAction={{ label: 'New Invoice', onClick: () => router.push('/accounting/customer-invoices/new') }}
 *     secondaryAction={{ label: 'Import from Sage', href: '/accounting/migration' }}
 *   />
 */

import type { LucideIcon } from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ActionButton {
  label: string;
  onClick?: () => void;
  href?: string;
}

interface EmptyStateProps {
  /** Lucide icon component rendered at the top */
  icon: LucideIcon;
  title: string;
  description?: string;
  primaryAction?: ActionButton;
  secondaryAction?: ActionButton;
  className?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function ActionLink({ action, primary }: { action: ActionButton; primary: boolean }) {
  const base = cn(
    'inline-flex items-center justify-center px-4 py-2 rounded-lg text-sm font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500',
    primary
      ? 'bg-teal-600 text-white hover:bg-teal-700 dark:bg-teal-500 dark:hover:bg-teal-600'
      : 'border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
  );

  if (action.href) {
    return (
      <Link href={action.href} className={base}>
        {action.label}
      </Link>
    );
  }

  return (
    <button type="button" onClick={action.onClick} className={base}>
      {action.label}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

// // WORKING: Pure presentational component — no state
export function EmptyState({
  icon: Icon,
  title,
  description,
  primaryAction,
  secondaryAction,
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center text-center py-16 px-6',
        className
      )}
    >
      {/* Icon container */}
      <div className="mb-4 flex items-center justify-center w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800">
        <Icon className="w-8 h-8 text-gray-400 dark:text-gray-500" strokeWidth={1.5} />
      </div>

      {/* Text */}
      <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100 mb-1">
        {title}
      </h3>
      {description && (
        <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs leading-relaxed">
          {description}
        </p>
      )}

      {/* Actions */}
      {(primaryAction || secondaryAction) && (
        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          {primaryAction && <ActionLink action={primaryAction} primary />}
          {secondaryAction && <ActionLink action={secondaryAction} primary={false} />}
        </div>
      )}
    </div>
  );
}

