/**
 * Drawer — slide-in panel from the right side of the screen.
 * // WORKING: Portal-based, ESC key, backdrop click-to-close, smooth animation
 */

import { useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { cn } from '@/utils/cn';

type DrawerWidth = 'sm' | 'md' | 'lg' | 'xl';

interface DrawerProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  width?: DrawerWidth;
  className?: string;
}

const WIDTH_CLASSES: Record<DrawerWidth, string> = {
  sm: 'w-80',    // 320px
  md: 'w-[480px]',
  lg: 'w-[640px]',
  xl: 'w-[800px]',
};

// WORKING: Drawer component with portal rendering
export function Drawer({
  open,
  onClose,
  title,
  children,
  width = 'md',
  className,
}: DrawerProps) {
  const previouslyFocused = useRef<Element | null>(null);

  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    },
    [onClose]
  );

  useEffect(() => {
    if (open) {
      previouslyFocused.current = document.activeElement;
      document.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
    } else {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
      if (previouslyFocused.current instanceof HTMLElement) {
        previouslyFocused.current.focus();
      }
    }
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = '';
    };
  }, [open, handleKeyDown]);

  if (typeof window === 'undefined') return null;

  const drawer = (
    <div
      aria-modal="true"
      aria-label={title}
      role="dialog"
      className={cn(
        'fixed inset-0 z-50 flex justify-end',
        !open && 'pointer-events-none'
      )}
    >
      {/* Backdrop */}
      <div
        aria-hidden="true"
        onClick={onClose}
        className={cn(
          'absolute inset-0 bg-black/50 transition-opacity duration-300',
          open ? 'opacity-100' : 'opacity-0'
        )}
      />

      {/* Panel */}
      <div
        className={cn(
          'relative flex h-full flex-col bg-white shadow-xl',
          'dark:bg-gray-900',
          'transition-transform duration-300 ease-in-out',
          WIDTH_CLASSES[width],
          open ? 'translate-x-0' : 'translate-x-full',
          className
        )}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-gray-200 px-6 py-4 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
            {title}
          </h2>
          <button
            type="button"
            aria-label="Close drawer"
            onClick={onClose}
            className={cn(
              'rounded-md p-1 text-gray-400 transition-colors',
              'hover:bg-gray-100 hover:text-gray-600',
              'dark:hover:bg-gray-800 dark:hover:text-gray-300',
              'focus:outline-none focus:ring-2 focus:ring-teal-500'
            )}
          >
            <X size={20} aria-hidden="true" />
          </button>
        </div>

        {/* Scrollable content */}
        <div className="flex-1 overflow-y-auto px-6 py-4">{children}</div>
      </div>
    </div>
  );

  return createPortal(drawer, document.body);
}

/**
 * Toast — notification system with context provider and useToast() hook.
 *
 * Setup: wrap the app (or _app.tsx) with <ToastProvider>.
 *
 * Usage:
 *   const { toast } = useToast();
 *   toast.success('Saved successfully');
 *   toast.error('Something went wrong', { duration: 8000 });
 */

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from 'react';
import { createPortal } from 'react-dom';
import {
  CheckCircle,
  AlertCircle,
  AlertTriangle,
  Info,
  X,
} from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ToastType = 'success' | 'error' | 'warning' | 'info';

export interface ToastOptions {
  /** Auto-dismiss duration in ms. 0 = never auto-dismiss. Default: 5000 */
  duration?: number;
}

export interface ToastItem extends Required<ToastOptions> {
  id: string;
  type: ToastType;
  message: string;
}

interface ToastContextValue {
  toast: {
    success: (message: string, opts?: ToastOptions) => void;
    error: (message: string, opts?: ToastOptions) => void;
    warning: (message: string, opts?: ToastOptions) => void;
    info: (message: string, opts?: ToastOptions) => void;
  };
  dismiss: (id: string) => void;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_DURATION = 5000;

const TOAST_STYLES: Record<ToastType, { bg: string; icon: ReactNode; text: string }> = {
  success: {
    bg: 'bg-green-50 dark:bg-green-900/30 border-green-200 dark:border-green-700',
    text: 'text-green-800 dark:text-green-200',
    icon: <CheckCircle className="w-5 h-5 text-green-500 shrink-0" />,
  },
  error: {
    bg: 'bg-red-50 dark:bg-red-900/30 border-red-200 dark:border-red-700',
    text: 'text-red-800 dark:text-red-200',
    icon: <AlertCircle className="w-5 h-5 text-red-500 shrink-0" />,
  },
  warning: {
    bg: 'bg-amber-50 dark:bg-amber-900/30 border-amber-200 dark:border-amber-700',
    text: 'text-amber-800 dark:text-amber-200',
    icon: <AlertTriangle className="w-5 h-5 text-amber-500 shrink-0" />,
  },
  info: {
    bg: 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-700',
    text: 'text-blue-800 dark:text-blue-200',
    icon: <Info className="w-5 h-5 text-blue-500 shrink-0" />,
  },
};

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

const ToastContext = createContext<ToastContextValue | null>(null);

// ---------------------------------------------------------------------------
// Single toast tile
// ---------------------------------------------------------------------------

interface ToastTileProps {
  item: ToastItem;
  onDismiss: (id: string) => void;
}

function ToastTile({ item, onDismiss }: ToastTileProps) {
  const style = TOAST_STYLES[item.type];
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (item.duration <= 0) return;
    timerRef.current = setTimeout(() => onDismiss(item.id), item.duration);
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [item.id, item.duration, onDismiss]);

  return (
    <div
      role="alert"
      aria-live="assertive"
      className={cn(
        'flex items-start gap-3 w-80 max-w-full p-4 rounded-lg border shadow-lg',
        'animate-in slide-in-from-right-4 fade-in-0 duration-300',
        style.bg
      )}
    >
      {style.icon}
      <p className={cn('flex-1 text-sm font-medium leading-snug', style.text)}>
        {item.message}
      </p>
      <button
        type="button"
        aria-label="Dismiss notification"
        onClick={() => onDismiss(item.id)}
        className={cn(
          'shrink-0 p-0.5 rounded transition-opacity opacity-60 hover:opacity-100',
          style.text
        )}
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Provider
// ---------------------------------------------------------------------------

let _nextId = 1;
function uid() {
  return `toast-${_nextId++}`;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  const dismiss = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const add = useCallback(
    (type: ToastType, message: string, opts?: ToastOptions) => {
      const item: ToastItem = {
        id: uid(),
        type,
        message,
        duration: opts?.duration ?? DEFAULT_DURATION,
      };
      setToasts((prev) => [...prev, item]);
    },
    []
  );

  const toast: ToastContextValue['toast'] = {
    success: (msg, opts) => add('success', msg, opts),
    error: (msg, opts) => add('error', msg, opts),
    warning: (msg, opts) => add('warning', msg, opts),
    info: (msg, opts) => add('info', msg, opts),
  };

  return (
    <ToastContext.Provider value={{ toast, dismiss }}>
      {children}
      {mounted &&
        createPortal(
          <div
            aria-label="Notifications"
            className="fixed bottom-4 right-4 z-50 flex flex-col gap-2 items-end"
          >
            {toasts.map((item) => (
              <ToastTile key={item.id} item={item} onDismiss={dismiss} />
            ))}
          </div>,
          document.body
        )}
    </ToastContext.Provider>
  );
}

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------

// // WORKING: Throws a helpful error when used outside provider
export function useToast(): ToastContextValue {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used inside <ToastProvider>');
  return ctx;
}

/**
 * Breadcrumb — accessible breadcrumb navigation with responsive collapsing.
 *
 * Usage:
 *   <Breadcrumb
 *     items={[
 *       { label: 'Accounting', href: '/accounting' },
 *       { label: 'Invoices', href: '/accounting/customer-invoices' },
 *       { label: 'INV-0042' },
 *     ]}
 *   />
 */

import { useState } from 'react';
import Link from 'next/link';
import { ChevronRight, MoreHorizontal } from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type BreadcrumbSeparator = 'chevron' | 'slash';

export interface BreadcrumbItem {
  label: string;
  href?: string;
  onClick?: () => void;
}

interface BreadcrumbProps {
  items: BreadcrumbItem[];
  separator?: BreadcrumbSeparator;
  className?: string;
  /** Max items shown before collapsing. 0 = no collapse. Default: 4 */
  maxVisible?: number;
}

// ---------------------------------------------------------------------------
// Separator
// ---------------------------------------------------------------------------

function Separator({ type }: { type: BreadcrumbSeparator }) {
  if (type === 'chevron') {
    return (
      <ChevronRight
        aria-hidden="true"
        className="w-4 h-4 text-gray-400 dark:text-gray-500 shrink-0"
      />
    );
  }
  return (
    <span aria-hidden="true" className="text-gray-400 dark:text-gray-500 select-none">
      /
    </span>
  );
}

// ---------------------------------------------------------------------------
// Item renderers
// ---------------------------------------------------------------------------

function BreadcrumbLink({ item }: { item: BreadcrumbItem }) {
  const base =
    'text-sm text-gray-500 dark:text-gray-400 hover:text-teal-600 dark:hover:text-teal-400 transition-colors truncate max-w-[10rem]';

  if (item.href) {
    return (
      <Link href={item.href} className={base}>
        {item.label}
      </Link>
    );
  }
  if (item.onClick) {
    return (
      <button type="button" onClick={item.onClick} className={cn(base, 'focus:outline-none')}>
        {item.label}
      </button>
    );
  }
  // No href/onClick — render as plain text (fallback)
  return <span className={base}>{item.label}</span>;
}

function BreadcrumbCurrent({ label }: { label: string }) {
  return (
    <span
      aria-current="page"
      className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate max-w-[12rem]"
    >
      {label}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

// // WORKING: Collapsing handled via local state; no router dependency
export function Breadcrumb({
  items,
  separator = 'chevron',
  className,
  maxVisible = 4,
}: BreadcrumbProps) {
  const [expanded, setExpanded] = useState(false);

  if (items.length === 0) return null;

  const shouldCollapse = maxVisible > 0 && !expanded && items.length > maxVisible;

  // Build visible items: always show first + last, collapse the middle
  let visibleItems: (BreadcrumbItem | null)[] = items;
  if (shouldCollapse) {
    // Show first, ellipsis placeholder, then last (maxVisible - 2) items
    const tail = items.slice(-(maxVisible - 1));
    visibleItems = [items[0] ?? null, null, ...tail];
  }

  const lastIndex = visibleItems.length - 1;

  return (
    <nav aria-label="Breadcrumb" className={cn('flex items-center', className)}>
      <ol className="flex items-center flex-wrap gap-1">
        {visibleItems.map((item, idx) => {
          const isLast = idx === lastIndex;

          if (item === null) {
            // Ellipsis
            return (
              <li key="ellipsis" className="flex items-center gap-1">
                <Separator type={separator} />
                <button
                  type="button"
                  aria-label="Show all breadcrumbs"
                  onClick={() => setExpanded(true)}
                  className="p-0.5 rounded text-gray-400 hover:text-teal-600 dark:hover:text-teal-400 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500"
                >
                  <MoreHorizontal className="w-4 h-4" />
                </button>
              </li>
            );
          }

          return (
            <li key={`${item.label}-${idx}`} className="flex items-center gap-1">
              {idx > 0 && <Separator type={separator} />}
              {isLast ? (
                <BreadcrumbCurrent label={item.label} />
              ) : (
                <BreadcrumbLink item={item} />
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

/**
 * Tabs — accessible horizontal tab bar with optional URL sync, count badges,
 * and two visual variants: 'underline' and 'pill'.
 *
 * Usage (controlled, no URL sync):
 *   <Tabs
 *     tabs={[
 *       { id: 'all', label: 'All', count: 42 },
 *       { id: 'draft', label: 'Draft', count: 3, icon: FileText },
 *     ]}
 *     activeTab="all"
 *     onChange={setActiveTab}
 *   />
 *
 * Usage (URL sync via ?tab= query param):
 *   <Tabs tabs={tabs} urlParam="tab" />
 */

import { useCallback, type ReactNode } from 'react';
import { useRouter } from 'next/router';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type TabVariant = 'underline' | 'pill';

export interface TabDefinition {
  id: string;
  label: string;
  /** Optional numeric badge shown next to the label */
  count?: number;
  /** Optional Lucide icon shown before the label */
  icon?: LucideIcon;
  /** Disable this tab */
  disabled?: boolean;
}

interface TabsBaseProps {
  tabs: TabDefinition[];
  variant?: TabVariant;
  className?: string;
  /** ARIA label for the tablist */
  'aria-label'?: string;
}

/** Controlled mode — caller manages activeTab state */
interface TabsControlledProps extends TabsBaseProps {
  activeTab: string;
  onChange: (id: string) => void;
  urlParam?: never;
}

/** URL-sync mode — reads/writes Next.js router query param */
interface TabsUrlProps extends TabsBaseProps {
  urlParam: string;
  activeTab?: string;
  onChange?: (id: string) => void;
}

type TabsProps = TabsControlledProps | TabsUrlProps;

// ---------------------------------------------------------------------------
// Count badge
// ---------------------------------------------------------------------------

function CountBadge({ count, active }: { count: number; active: boolean }) {
  return (
    <span
      className={cn(
        'ml-1.5 inline-flex items-center justify-center rounded-full px-1.5 py-0.5 text-xs font-medium leading-none tabular-nums',
        active
          ? 'bg-teal-100 text-teal-700 dark:bg-teal-800/40 dark:text-teal-300'
          : 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400'
      )}
    >
      {count}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Tab button
// ---------------------------------------------------------------------------

interface TabButtonProps {
  tab: TabDefinition;
  active: boolean;
  variant: TabVariant;
  onClick: () => void;
}

function TabButton({ tab, active, variant, onClick }: TabButtonProps) {
  const Icon = tab.icon;

  const underlineClasses = cn(
    'relative inline-flex items-center gap-1.5 px-1 pb-3 pt-1 text-sm font-medium border-b-2 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500 focus-visible:ring-offset-1',
    active
      ? 'border-teal-600 text-teal-600 dark:border-teal-400 dark:text-teal-400'
      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300 dark:text-gray-400 dark:hover:text-gray-200 dark:hover:border-gray-600',
    tab.disabled && 'cursor-not-allowed opacity-50 pointer-events-none'
  );

  const pillClasses = cn(
    'inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500',
    active
      ? 'bg-teal-600 text-white dark:bg-teal-500'
      : 'text-gray-600 hover:bg-gray-100 hover:text-gray-900 dark:text-gray-400 dark:hover:bg-gray-700 dark:hover:text-gray-100',
    tab.disabled && 'cursor-not-allowed opacity-50 pointer-events-none'
  );

  return (
    <button
      type="button"
      role="tab"
      id={`tab-${tab.id}`}
      aria-selected={active}
      aria-controls={`panel-${tab.id}`}
      aria-disabled={tab.disabled}
      disabled={tab.disabled}
      tabIndex={active ? 0 : -1}
      onClick={onClick}
      className={variant === 'underline' ? underlineClasses : pillClasses}
    >
      {Icon && <Icon className="w-4 h-4 shrink-0" aria-hidden="true" />}
      {tab.label}
      {tab.count !== undefined && <CountBadge count={tab.count} active={active} />}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Root component
// ---------------------------------------------------------------------------

// // WORKING: URL sync reads from router.query; shallow push keeps scroll position
export function Tabs(props: TabsProps): ReactNode {
  const router = useRouter();

  // Resolve active tab
  let activeTab: string;
  if ('urlParam' in props && props.urlParam) {
    const fromUrl = router.query[props.urlParam];
    activeTab =
      props.activeTab ??
      (typeof fromUrl === 'string' ? fromUrl : null) ??
      props.tabs[0]?.id ??
      '';
  } else {
    activeTab = (props as TabsControlledProps).activeTab ?? props.tabs[0]?.id ?? '';
  }

  const handleChange = useCallback(
    (id: string) => {
      if ('urlParam' in props && props.urlParam) {
        void router.push(
          { query: { ...router.query, [props.urlParam]: id } },
          undefined,
          { shallow: true }
        );
        props.onChange?.(id);
      } else {
        (props as TabsControlledProps).onChange(id);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [router, props]
  );

  const { variant = 'underline', className } = props;

  return (
    <div
      role="tablist"
      aria-label={props['aria-label'] ?? 'Tabs'}
      className={cn(
        'flex',
        variant === 'underline'
          ? 'gap-6 border-b border-gray-200 dark:border-gray-700'
          : 'gap-1 p-1 bg-gray-100 dark:bg-gray-800 rounded-xl w-fit',
        className
      )}
    >
      {props.tabs.map((tab) => (
        <TabButton
          key={tab.id}
          tab={tab}
          active={tab.id === activeTab}
          variant={variant}
          onClick={() => handleChange(tab.id)}
        />
      ))}
    </div>
  );
}

/**
 * EmptyState — centered empty-state block with an icon, title, description,
 * and optional primary / secondary action buttons.
 *
 * Usage:
 *   <EmptyState
 *     icon={FileText}
 *     title="No invoices yet"
 *     description="Create your first invoice to get started."
 *     primaryAction={{ label: 'New Invoice', onClick: () => router.push('/accounting/customer-invoices/new') }}
 *     secondaryAction={{ label: 'Import from Sage', href: '/accounting/migration' }}
 *   />
 */

import type { LucideIcon } from 'lucide-react';
import Link from 'next/link';
import { cn } from '@/utils/cn';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ActionButton {
  label: string;
  onClick?: () => void;
  href?: string;
}

interface EmptyStateProps {
  /** Lucide icon component rendered at the top */
  icon: LucideIcon;
  title: string;
  description?: string;
  primaryAction?: ActionButton;
  secondaryAction?: ActionButton;
  className?: string;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function ActionLink({ action, primary }: { action: ActionButton; primary: boolean }) {
  const base = cn(
    'inline-flex items-center justify-center px-4 py-2 rounded-lg text-sm font-medium transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-teal-500',
    primary
      ? 'bg-teal-600 text-white hover:bg-teal-700 dark:bg-teal-500 dark:hover:bg-teal-600'
      : 'border border-gray-300 dark:border-gray-600 text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
  );

  if (action.href) {
    return (
      <Link href={action.href} className={base}>
        {action.label}
      </Link>
    );
  }

  return (
    <button type="button" onClick={action.onClick} className={base}>
      {action.label}
    </button>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

// // WORKING: Pure presentational component — no state
export function EmptyState({
  icon: Icon,
  title,
  description,
  primaryAction,
  secondaryAction,
  className,
}: EmptyStateProps) {
  return (
    <div
      className={cn(
        'flex flex-col items-center justify-center text-center py-16 px-6',
        className
      )}
    >
      {/* Icon container */}
      <div className="mb-4 flex items-center justify-center w-16 h-16 rounded-full bg-gray-100 dark:bg-gray-800">
        <Icon className="w-8 h-8 text-gray-400 dark:text-gray-500" strokeWidth={1.5} />
      </div>

      {/* Text */}
      <h3 className="text-base font-semibold text-gray-900 dark:text-gray-100 mb-1">
        {title}
      </h3>
      {description && (
        <p className="text-sm text-gray-500 dark:text-gray-400 max-w-xs leading-relaxed">
          {description}
        </p>
      )}

      {/* Actions */}
      {(primaryAction || secondaryAction) && (
        <div className="mt-6 flex flex-wrap items-center justify-center gap-3">
          {primaryAction && <ActionLink action={primaryAction} primary />}
          {secondaryAction && <ActionLink action={secondaryAction} primary={false} />}
        </div>
      )}
    </div>
  );
}

