  const [activeSection, setActiveSection] = useState('Button');
  const [loadingDemo, setLoadingDemo] = useState(false);

  const simulateLoading = () => {
    setLoadingDemo(true);
    setTimeout(() => setLoadingDemo(false), 2000);
